The provided solution in Python uses LU decomposition for calculating the determinant of the submatrix, which is more efficient and generalizable to larger matrices:

```python
import numpy as np
from typing import List

def lu_decomposition(A: np.ndarray) -> (np.ndarray, np.ndarray):
    """Perform LU decomposition on a square matrix A."""
    n = A.shape[0]
    L = np.zeros((n, n))
    U = np.copy(A)

    for k in range(n):
        L[k, k] = 1
        for i in range(k + 1, n):
            factor = A[i, k] / A[k, k]
            L[i, k] = factor
            for j in range(k + 1, n):
                A[i, j] -= factor * A[k, j]
            A[i, k] = 0

    return L, A  # U is stored in the original matrix A after decomposition

def determinant_lu(A: np.ndarray) -> float:
    """Calculate the determinant of a matrix A using LU decomposition."""
    _, U = lu_decomposition(A)
    return np.prod(np.diag(U))

def calculate_minor(matrix: List[List[float]], row: int, col: int) -> float:
    """
    Calculates the minor of a matrix element using LU decomposition for efficiency.

    Parameters:
    - matrix: A square list of lists representing the matrix.
    - row: The row index of the element whose minor we want to calculate.
    - col: The column index of the element whose minor we want to calculate.

    Returns:
    - The minor value.

    Raises:
    - ValueError: If the matrix is not square or if row/col indices are out of bounds.
    """
    A = np.array(matrix)
    n = A.shape[0]

    if A.shape[1] != n:
        raise ValueError("Matrix must be square.")

    if row < 0 or row >= n or col < 0 or col >= n:
        raise ValueError("Row and column indices must be within the matrix dimensions.")

    if n == 2:
        return matrix[1 - row][1 - col]

    submatrix = np.delete(np.delete(A, row, axis=0), col, axis=1)
    return determinant_lu(submatrix)

# Example usage:
