try:
    minor_value_2x2 = calculate_minor(matrix_2x2, 0, 0)
    print(f"Minor of 2x2 Matrix: {minor_value_2x2}")  # Expected output: 8
except ValueError as e:
    print(f"Error: {e}")

matrix_3x3 = [[4, 6, 1], [3, 8, 2], [7, 5, 9]]
try:
    minor_value_3x3 = calculate_minor(matrix_3x3, 1, 1)
    print(f"Minor of 3x3 Matrix: {minor_value_3x3}")  # Expected output depends on the matrix
except ValueError as e:
    print(f"Error: {e}")
```

