// @name         Dr. Torkzadeh Auto-Reservation
// @namespace    http://tampermonkey.net/
// @version      1.0
// @description  Automated reservation monitoring and cross-tab triggering
// @author       Assistant
// @match        http://www.drtorkzadeh.com/*
// @grant        none
// ==/UserScript==
*/

(function() {
    'use strict';

    const MAIN_URL = "http://www.drtorkzadeh.com/";
    const FORBIDDEN_TEXT = "رزرو فقط در ساعات 9 صبح تا 10 صبح امکان پذیر است";

    // --- ZERO STEP: Ensure it only runs in the first instance/tab of this site ---
    // We use sessionStorage to mark the "Master" tab.
    if (!sessionStorage.getItem('isMasterTab')) {
        sessionStorage.setItem('isMasterTab', 'true');
    } else {
        // If you want it strictly only in one tab, uncomment the line below:
        // console.log("Secondary tab detected, monitoring logic disabled.");
    }

    // Function to check if current time is between 22:30 and 03:30
    function isCorrectTime() {
        const now = new Date();
        const hours = now.getHours();
        const minutes = now.getMinutes();
        const totalMinutes = hours * 60 + minutes;

        const start = 22 * 60 + 30; // 22:30
        const end = 3 * 60 + 30;    // 03:30

        // Time range crosses midnight
        return (totalMinutes >= start || totalMinutes <= end);
    }

    // --- FIRST STEP: Check if we are on the main page ---
    const isMainPage = window.location.href === MAIN_URL || window.location.pathname === "/" || window.location.pathname === "/index.php";

    if (isMainPage) {
        console.log("Main page detected. Starting logic...");

        // --- SECOND STEP: Time Check ---
        if (!isCorrectTime()) {
            console.log("Outside of allowed time (22:30 - 03:30). Waiting...");
            setTimeout(() => location.reload(), 60000); // Check again in 1 minute
            return;
        }

        // --- THIRD STEP: Check for forbidden text ---
        if (document.body.innerText.includes(FORBIDDEN_TEXT)) {
            console.log("Text found. Reloading in 5 seconds...");
            setTimeout(() => {
                location.reload();
            }, 5000);
        } 
        // --- FOURTH STEP: Text NOT found, signal the other tab ---
        else {
            console.log("Text NOT found! Signaling second tab...");
            localStorage.setItem('triggerBooking', Date.now()); // Send signal via localStorage
        }
    } 

    // --- FIFTH STEP: Logic for the "Next Tab" (The one with the submit button) ---
    // This part runs on any page that isn't the main page, or specifically where the button exists.
    function checkForSignal() {
        // Listen for the signal from the main tab
        window.addEventListener('storage', (event) => {
            if (event.key === 'triggerBooking') {
                const submitButton = document.querySelector('input[type="submit"]#submit');
                if (submitButton) {
                    console.log("Signal received! Clicking submit...");
                    submitButton.click();
                    // Stop the code after clicking
                    localStorage.removeItem('triggerBooking');
                }
            }
        });
    }

    checkForSignal();

})();
