```python
from flask import Flask, request, jsonify
from flask_cors import CORS
import openai
import os

app = Flask(__name__)
CORS(app)  # This allows your Square site to talk to this script

# Set your OpenAI API Key
openai.api_key = "YOUR_OPENAI_API_KEY"

@app.route('/generate-spell', methods=['POST'])
def generate_spell():
    data = request.json
    recipe_text = data.get('recipe', '')

    if not recipe_text:
        return jsonify({"error": "No recipe provided"}), 400

    try:
        # The prompt tells the AI to act as a folklore expert
        prompt = f"""
        Act as an expert in ancient folklore, kitchen witchery, and herbalism. 
        I will give you a recipe. Extract the main ingredients and create a 
        mystical 'spell' or 'incantation' based on the traditional symbolic 
        meanings of those ingredients. 

        Recipe: {recipe_text}

        Format the response with:
        1. The Spell Name
        2. The Intent (e.g., Prosperity, Protection, Love)
        3. The Incantation (a short poem or chant)
        4. Symbolic meaning of 2 key ingredients.
        """

        response = openai.ChatCompletion.create(
            model="gpt-3.5-turbo",
            messages=[{"role": "user", "content": prompt}]
        )

        spell = response.choices[0].message.content
        return jsonify({"spell": spell})

    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
```

