### Part 1: The Python Backend (Flask)

This version adds support for **OCR (Optical Character Recognition)** using `pytesseract` for images and `pdfplumber` for PDFs. 

**Note:** To run this, your server (e.g., Render or Heroku) must have the Tesseract binary installed. If you are using Render, you can add it via a "Build Filter" or a custom Dockerfile.

```python
import os
import re
import pdfplumber
from PIL import Image
import pytesseract
from flask import Flask, request, jsonify
from flask_cors import CORS
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address
import openai
from duckduckgo_search import DDGS

app = Flask(__name__)
CORS(app)

# Rate limiting to prevent abuse
limiter = Limiter(
    get_remote_address,
    app=app,
    default_limits=["100 per day", "10 per hour"],
    storage_uri="memory://",
)

openai.api_key = os.getenv("OPENAI_API_KEY")

def extract_text_from_pdf(file):
    with pdfplumber.open(file) as pdf:
        return " ".join([page.extract_text() for page in pdf.pages if page.extract_text()])

def extract_text_from_image(file):
    img = Image.open(file)
    return pytesseract.image_to_string(img)

def sanitize_input(text):
    return re.sub(r'[^\w\s,]', '', text).strip()

def gather_internet_lore(ingredients):
    lore_context = ""
    try:
        with DDGS() as ddgs:
            for ingredient in ingredients[:2]:
                query = f"magical folklore and symbolic meaning of {sanitize_input(ingredient)}"
                results = list(ddgs.text(query, max_results=2))
                lore_context += f"\nLore for {ingredient}:\n" + "\n".join([r['body'] for r in results])
    except Exception:
        return "No additional folklore found."
    return lore_context

@app.route('/generate-spell', methods=['POST'])
@limiter.limit("5 per minute")
def generate_spell():
    recipe_text = ""

    # Check if a file was uploaded
    if 'recipe_file' in request.files:
        file = request.files['recipe_file']
        if file.filename.endswith('.pdf'):
            recipe_text = extract_text_from_pdf(file)
        elif file.filename.lower().endswith(('.png', '.jpg', '.jpeg')):
            recipe_text = extract_text_from_image(file)

    # Fallback to text input if no file or file extraction failed
    if not recipe_text:
        recipe_text = request.form.get('recipe_text', '')

    if not recipe_text or len(recipe_text) < 10:
        return jsonify({"error": "Could not read recipe. Please upload a clear file or paste text."}), 400

    try:
        # Use AI to clean up the messy OCR/PDF text into a clean ingredient list
        extraction_response = openai.ChatCompletion.create(
            model="gpt-3.5-turbo",
            messages=[
                {"role": "system", "content": "Extract only the main ingredients from this recipe text as a comma-separated list."},
                {"role": "user", "content": recipe_text[:2000]} # Limit input size
            ]
        )
        ingredients = extraction_response.choices[0].message.content.split(',')
        ingredients = [sanitize_input(i) for i in ingredients[:5]]

        # Gather Lore and Generate Spell
        internet_research = gather_internet_lore(ingredients)

        spell_response = openai.ChatCompletion.create(
            model="gpt-3.5-turbo",
            messages=[
                {"role": "system", "content": "You are a Kitchen Witch. Create a rhyming spell based on ingredients and lore."},
                {"role": "user", "content": f"Ingredients: {ingredients}. Research: {internet_research}"}
            ]
        )

        return jsonify({"spell": spell_response.choices[0].message.content, "ingredients": ingredients})

    except Exception as e:
        return jsonify({"error": "The mystical connection failed."}), 500

if __name__ == '__main__':
    app.run(debug=False)
```

