def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def get_ingredient_lore(ingredient):
    """Searches the web for mystical properties."""
    cached = cache.get(f"lore_{ingredient}")
    if cached: return cached

    try:
        with DDGS() as ddgs:
            # Query engineering for mystical relevance
            query = f"{ingredient} magical folklore and esoteric correspondences"
            results = list(ddgs.text(query, max_results=2))
            lore = "\n".join([r['body'] for r in results])
            cache.set(f"lore_{ingredient}", lore)
            return lore
    except:
        return ""

@app.route('/generate-spell', methods=['POST'])
@limiter.limit("5 per minute")
def generate_spell():
    recipe_text = ""

    # 1. Handle File Upload (OCR/PDF)
    if 'recipe_file' in request.files:
        file = request.files['recipe_file']
        if file and allowed_file(file.filename):
            filename = secure_filename(file.filename)
            if filename.endswith('.pdf'):
                with pdfplumber.open(file) as pdf:
                    recipe_text = " ".join([p.extract_text() for p in pdf.pages if p.extract_text()])
            else:
                img = Image.open(file)
                img.thumbnail((1000, 1000)) # Resize for faster OCR
                recipe_text = pytesseract.image_to_string(img)

    # 2. Fallback to Text Input
    if not recipe_text:
        recipe_text = request.form.get('recipe_text', '')

    if len(recipe_text) < 5:
        return jsonify({"error": "Please provide a clearer recipe."}), 400

    try:
        # 3. AI Ingredient Extraction
        extract_res = openai.ChatCompletion.create(
            model="gpt-3.5-turbo",
            messages=[{"role": "system", "content": "Extract only the main food/herb ingredients as a comma-separated list."},
                      {"role": "user", "content": recipe_text[:1500]}]
        )
        ingredients = [i.strip() for i in extract_res.choices[0].message.content.split(',')][:4]

        # 4. Parallel Lore Gathering
        with ThreadPoolExecutor(max_workers=3) as executor:
            lore_bits = list(executor.map(get_ingredient_lore, ingredients))
        lore_context = "\n".join(lore_bits)

        # 5. Final Spell Generation
        final_spell = openai.ChatCompletion.create(
            model="gpt-3.5-turbo",
            messages=[
                {"role": "system", "content": "You are a Kitchen Witch. Create a rhyming spell and a 'Folklore Fact' based on the provided research."},
                {"role": "user", "content": f"Ingredients: {ingredients}\nResearch: {lore_context}"}
            ]
        )

        return jsonify({
            "spell": final_spell.choices[0].message.content,
            "ingredients": ingredients
        })

    except Exception as e:
        return jsonify({"error": "The mystical energies are blocked."}), 500

if __name__ == '__main__':
