# Three.js implementation using IPython display
class ThreeJSFunctionGrapher:
    def __init__(self):
        self.width = 800
        self.height = 600
        self.function_str = "x*x - y*y"  # Hyperbolic paraboloid
        self.x_min, self.x_max = -1, 1
