    def get_geometry_info(self):
        """Get information about the generated geometry"""
        segments = int((self.x_max - self.x_min) / self.step)
        vertices = (segments + 1) * (segments + 1)
        faces = segments * segments * 2

        return {
            'function': self.function_str,
