    common_typos = {
        'srcdirr': 'srcdir',
        'pkgdirr': 'pkgdir',
        'buid': 'build',
        'pakcage': 'package',
        'instal': 'install',
        'applicaton': 'application',
        'applicatons': 'applications',
        'directoy': 'directory',
        'diretory': 'directory',
    }

    # Check for unbalanced braces/parentheses
    brace_count = 0
    paren_count = 0
    in_function = False

    for i, line in enumerate(lines, 1):
        line_stripped = line.strip()

        # Skip comments
        if line_stripped.startswith('#'):
            continue

        # Check for typos
        line_lower = line.lower()
        for typo, correct in common_typos.items():
            if typo in line_lower and correct not in line_lower:
                results["syntax_errors"].append(
                    f"Line {i}: Possible typo '{typo}' should be '{correct}'"
                )

        # Check for unclosed quotes
        if '=' in line and not line_stripped.startswith('#'):
            parts = line.split('=', 1)
            if len(parts) == 2:
                value = parts[1].strip()
                if (value.startswith('"') and not value.endswith('"')) or \
                   (value.startswith("'") and not value.endswith("'")):
                    results["syntax_errors"].append(
                        f"Line {i}: Unclosed quotes in variable assignment"
                    )

        # Track braces for function boundaries
        if line_stripped.endswith('() {'):
            in_function = True
            brace_count = 1
        elif in_function:
            brace_count += line.count('{') - line.count('}')
            if brace_count == 0:
                in_function = False

        # Check for unbalanced parentheses in arrays
        if any(array in line for array in ['depends=(', 'source=(', 'sha256sums=(']):
            paren_count += 1
        elif line_stripped == ')' and paren_count > 0:
            paren_count -= 1

    if paren_count != 0:
        results["syntax_errors"].append("Unbalanced parentheses in arrays")

    # Check for undefined variables
    defined_vars = {'srcdir', 'pkgdir', 'pkgname', 'pkgver', 'pkgrel', '_pkgname'}
    for line in lines:
        if '=' in line and not line.strip().startswith('#'):
            var_name = line.split('=')[0].strip()
            if not var_name.endswith('()'):
                defined_vars.add(var_name)

    for i, line in enumerate(lines, 1):
        # Find variable references
        matches = re.findall(r'\$\{?(\w+)\}?', line)
        for match in matches:
            if match not in defined_vars and not match.startswith('_'):
                results["syntax_errors"].append(
                    f"Line {i}: Variable '${match}' might be undefined"
                )

