def analyze_sed_command(line_num: int, line: str, results: Dict[str, List[str]]) -> None:
    """Analyze the sed command for .desktop file modification."""

    results["desktop_file_analysis"].append(f"Line {line_num}: Desktop file modification found")

    # Extract the sed pattern
    pattern_match = re.search(r'sed\s+"s\|([^|]+)\|([^|]+)\|g"', line)
    if not pattern_match:
