    T = P * T_brk_max;
end

function P_new = ramp(P_cur, P_target, dP_up, dP_down, dt, P_min, P_max)
% ramp
% Rate-limited ramp from current pressure to target pressure.
% Inputs:
%   P_cur    - current pressure (normalized)
%   P_target - target pressure (normalized)
%   dP_up    - max increase rate [1/s]
%   dP_down  - max decrease rate [1/s]
%   dt       - timestep [s]
%   P_min    - minimum pressure clamp
%   P_max    - maximum pressure clamp
% Output:
%   P_new    - updated pressure after rate limit and clamping
    delta = P_target - P_cur;
    if delta > 0
        step = min(delta, dP_up*dt);
    else
        step = max(delta, -dP_down*dt);
    end
    P_new = P_cur + step;
    P_new = max(P_min, min(P_max, P_new));
end

function s = slip(v, w, R)
% slip
% Computes braking slip s = (v - w*R) / v, guarded near zero speed.
% Inputs:
%   v - vehicle longitudinal speed [m/s]
%   w - wheel angular speed [rad/s]
%   R - wheel effective radius [m]
% Output:
%   s - slip (bounded to [0, 1] for braking)
    if v <= 0.1
        % Near standstill: avoid divide-by-zero and chatter
        s = 0.0;
    else
        s = (v - w*R) / v;
        % For braking, bound to [0,1]
        s = max(0.0, min(1.0, s));
    end
end

function P_new = ABScycle(s, s_low, s_high, P_cur, dt, dP_up, dP_down, P_min, P_max)
% ABScycle
% Simple on-off ABS logic with rate-limited pressure changes.
% Inputs:
%   s        - current slip
%   s_low    - lower slip threshold
%   s_high   - upper slip threshold
%   P_cur    - current brake pressure (normalized)
%   dt       - timestep [s]
%   dP_up    - pressure increase rate [1/s]
%   dP_down  - pressure decrease rate [1/s]
%   P_min    - minimum pressure clamp
%   P_max    - maximum pressure clamp
% Output:
%   P_new    - updated pressure after ABS logic and rate limiting
    if s > s_high
        % Too much slip -> release pressure
        P_target = P_min;
    elseif s < s_low
        % Too little slip -> increase pressure
        P_target = P_max;
    else
        % Within band -> hold pressure
        P_target = P_cur;
    end
    P_new = ramp(P_cur, P_target, dP_up, dP_down, dt, P_min, P_max);
end

function mu = tiremodel(s, tire)
% tiremodel
% Burckhardt friction model for longitudinal mu vs. slip.
% Inputs:
%   s    - slip (0..1 typical for braking)
%   tire - struct with fields a1, a2, a3 (Burckhardt coefficients)
% Output:
%   mu   - friction coefficient
    s_eff = max(0.0, min(1.0, s));
    mu = tire.a1 * (1 - exp(-tire.a2 * s_eff)) - tire.a3 * s_eff;
    mu = max(0.0, mu);  % non-negative
end
