function [midpoints, normals, panel_lengths, tangents] = compute_control_points(panels)
    % Compute control points, normals, and tangents
    n = size(panels, 1);
    midpoints = zeros(n, 2);
    normals = zeros(n, 2);
    panel_lengths = zeros(n, 1);
    tangents = zeros(n, 2);

    for j = 1:n
        x_a = panels(j, 1);
        y_a = panels(j, 2);
        x_b = panels(j, 3);
        y_b = panels(j, 4);

        % Midpoint
        xm = (x_a + x_b) / 2;
        ym = (y_a + y_b) / 2;
        midpoints(j, :) = [xm ym];

        % Panel length
        dx = x_b - x_a;
        dy = y_b - y_a;
        L = sqrt(dx^2 + dy^2);
        panel_lengths(j) = L;

        % Tangent vector
        tx = dx / L;
        ty = dy / L;
        tangents(j, :) = [tx ty];

        % Normal vector (pointing outward)
        nx = dy / L;
        ny = -dx / L;
        normals(j, :) = [nx ny];
    end
end

function A = compute_influence_matrix(midpoints, normals, panels, panel_lengths)
    % Compute influence matrix using 3-point Gauss quadrature
    n = size(panels, 1);
    A = zeros(n);

    % 3-point Gauss quadrature points and weights
    gauss_points = [-sqrt(3/5), 5/9; 0, 8/9; sqrt(3/5), 5/9];

    for i = 1:n
        x_i = midpoints(i, 1);
        y_i = midpoints(i, 2);
        nx_i = normals(i, 1);
        ny_i = normals(i, 2);

        for j = 1:n
            if i == j
                A(i, j) = 0.5;
            else
                x_a_j = panels(j, 1);
                y_a_j = panels(j, 2);
                x_b_j = panels(j, 3);
                y_b_j = panels(j, 4);
                L_j = panel_lengths(j);

                sum_integral = 0;
                for k = 1:size(gauss_points, 1)
                    s = gauss_points(k, 1);
                    w = gauss_points(k, 2);

                    % Position on panel j
                    x_jk = x_a_j + (x_b_j - x_a_j) * (s + 1) / 2;
                    y_jk = y_a_j + (y_b_j - y_a_j) * (s + 1) / 2;

                    % Distance from control point i to current point on panel j
                    dx = x_i - x_jk;
                    dy = y_i - y_jk;
                    dist_sq = dx^2 + dy^2;

                    if dist_sq < 1e-12
                        contrib = 0;
                    else
                        % Dot product of distance vector and normal at control point
                        dot_product = dx * nx_i + dy * ny_i;
                        integrand = dot_product / dist_sq;
                        contrib = integrand * w;
                    end

                    sum_integral = sum_integral + contrib;
                end

                integral = sum_integral * (L_j / 2);
                A(i, j) = integral / (2 * pi);
            end
        end
    end
end

