    rhs = zeros(n, 1);

    for i = 1:n
        nx = normals(i, 1);
        ny = normals(i, 2);
        Vn = Vinf * (cos(alpha_rad) * nx + sin(alpha_rad) * ny);
        rhs(i) = -Vn;
    end
end

