function [panels, points] = read_panels(filename)
    % Read panel data from file with error handling

    try
        % Check if file exists
        if ~exist(filename, 'file')
            error('File %s not found', filename);
        end

        % Read points from file
        points = dlmread(filename);

        % Validate data format
        if size(points, 2) ~= 2
            error('File must contain exactly two columns (x, y)');
        end

        if size(points, 1) < 3
            error('At least 3 points are required to form panels');
        end

        % Check if points form a closed geometry
        if ~isequal(points(1,:), points(end,:))
            warning('The geometry is not closed. Adding connection from last to first point.');
        end

        % Create panels from points
        n = size(points, 1);
        panels = zeros(n, 4);
        for i = 1:n
            x1 = points(i, 1);
            y1 = points(i, 2);
            x2 = points(mod(i, n) + 1, 1);
            y2 = points(mod(i, n) + 1, 2);
            panels(i, :) = [x1 y1 x2 y2];
        end
    catch
        error('Failed to read panel data from file: %s', filename);
    end
end

function [midpoints, normals, panel_lengths, tangents] = compute_control_points(panels)
    % Compute control points, normals, and tangents

    n = size(panels, 1);
    midpoints = zeros(n, 2);
    normals = zeros(n, 2);
    panel_lengths = zeros(n, 1);
    tangents = zeros(n, 2);

    for j = 1:n
        x_a = panels(j, 1);
        y_a = panels(j, 2);
        x_b = panels(j, 3);
        y_b = panels(j, 4);

        % Midpoint
        xm = (x_a + x_b) / 2;
        ym = (y_a + y_b) / 2;
        midpoints(j, :) = [xm ym];

        % Panel length
        dx = x_b - x_a;
        dy = y_b - y_a;
        L = sqrt(dx^2 + dy^2);
        panel_lengths(j) = L;

        % Tangent vector
        tx = dx / L;
        ty = dy / L;
        tangents(j, :) = [tx ty];

        % Normal vector (pointing outward)
        nx = dy / L;
        ny = -dx / L;
        normals(j, :) = [nx ny];
    end
end

function A = compute_influence_matrix(midpoints, normals, panels, panel_lengths)
    % Compute influence matrix with source and vortex contributions

    n = size(panels, 1);
    A = zeros(n + 1);

    % 3-point Gauss quadrature points and weights
    gauss_points = [-sqrt(3/5), 5/9; 0, 8/9; sqrt(3/5), 5/9];

    for i = 1:n
        x_i = midpoints(i, 1);
        y_i = midpoints(i, 2);
        nx_i = normals(i, 1);
        ny_i = normals(i, 2);

        for j = 1:n
            x_a_j = panels(j, 1);
            y_a_j = panels(j, 2);
            x_b_j = panels(j, 3);
            y_b_j = panels(j, 4);
            L_j = panel_lengths(j);

            % Source influence
            sum_integral = 0;
            for k = 1:size(gauss_points, 1)
                s = gauss_points(k, 1);
                w = gauss_points(k, 2);

                % Position on panel j
                x_jk = x_a_j + (x_b_j - x_a_j) * (s + 1) / 2;
                y_jk = y_a_j + (y_b_j - y_a_j) * (s + 1) / 2;

                % Distance from control point i to current point on panel j
                dx = x_i - x_jk;
                dy = y_i - y_jk;
                dist_sq = dx^2 + dy^2;

                if dist_sq < 1e-12
                    contrib = 0;
                else
                    % Dot product of distance vector and normal at control point
                    dot_product = dx * nx_i + dy * ny_i;
                    integrand = dot_product / dist_sq;
                    contrib = integrand * w;
                end

                sum_integral = sum_integral + contrib;
            end

            integral = sum_integral * (L_j / 2);
            A(i, j) = integral / (2 * pi);

            % Vortex influence
            sum_integral = 0;
            for k = 1:size(gauss_points, 1)
                s = gauss_points(k, 1);
                w = gauss_points(k, 2);

                % Position on panel j
                x_jk = x_a_j + (x_b_j - x_a_j) * (s + 1) / 2;
                y_jk = y_a_j + (y_b_j - y_a_j) * (s + 1) / 2;

                % Distance from control point i to current point on panel j
                dx = x_i - x_jk;
                dy = y_i - y_jk;
                dist_sq = dx^2 + dy^2;

                if dist_sq < 1e-12
                    contrib = 0;
                else
                    % (dy * nx - dx * ny) / dist_sq
                    dot_product = dy * nx_i - dx * ny_i;
                    integrand = dot_product / dist_sq;
                    contrib = integrand * w;
                end

                sum_integral = sum_integral + contrib;
            end

            integral = sum_integral * (L_j / 2);
            A(i, n + 1) = A(i, n + 1) + integral / (2 * pi);
        end
    end

    % Kutta condition: γ₁ + γₙ = 0
    A(n + 1, 1) = 1;
    A(n + 1, n) = 1;
    A(n + 1, n + 1) = 0;
end

function rhs = compute_rhs(alpha_deg, Vinf, normals)
    % Compute right-hand side of the system

    alpha_rad = deg2rad(alpha_deg);
    n = size(normals, 1);
    rhs = zeros(n + 1, 1);

    for i = 1:n
        nx = normals(i, 1);
        ny = normals(i, 2);
        Vn = Vinf * (cos(alpha_rad) * nx + sin(alpha_rad) * ny);
        rhs(i) = -Vn;
    end
end

function [cp, theta, cp_analytical] = compute_pressure_coefficients(Vinf, alpha_deg, ...
    sigma, gamma, panels, midpoints, normals, tangents, panel_lengths)
    % Compute pressure coefficients

    n = size(panels, 1);
    cp = zeros(n, 1);

    % Try to compute angles for analytical solution (circular cylinder)
    try
        theta = atan2(midpoints(:,2), midpoints(:,1));
        cp_analytical = 1.0 - 4.0 * sin(theta).^2;
    catch
        theta = [];
        cp_analytical = [];
    end

    alpha_rad = deg2rad(alpha_deg);
    u_fs = Vinf * cos(alpha_rad);
    v_fs = Vinf * sin(alpha_rad);

    for i = 1:n
        x_i = midpoints(i, 1);
        y_i = midpoints(i, 2);
        tx = tangents(i, 1);
        ty = tangents(i, 2);

        u_ind = 0;
        v_ind = 0;

        for j = 1:n
            x_a_j = panels(j, 1);
            y_a_j = panels(j, 2);
            x_b_j = panels(j, 3);
            y_b_j = panels(j, 4);
            L_j = panel_lengths(j);
            sigma_j = sigma(j);

            % Source contribution
            for k = 1:3
                s = gauss_points(k, 1);
                w = gauss_points(k, 2);

                % Position on panel j
                x_jk = x_a_j + (x_b_j - x_a_j) * (s + 1) / 2;
                y_jk = y_a_j + (y_b_j - y_a_j) * (s + 1) / 2;

                % Distance from point i to current point on panel j
                dx = x_i - x_jk;
                dy = y_i - y_jk;
                dist_sq = dx^2 + dy^2;

                if dist_sq < 1e-12
                    u_contribution = 0;
                    v_contribution = 0;
                else
                    factor = sigma_j * w * (L_j / 2) / (2 * pi * dist_sq);
                    u_contribution = dx * factor;
                    v_contribution = dy * factor;
                end

                u_ind = u_ind + u_contribution;
                v_ind = v_ind + v_contribution;
            end

            % Vortex contribution
            for k = 1:3
                s = gauss_points(k, 1);
                w = gauss_points(k, 2);

                % Position on panel j
                x_jk = x_a_j + (x_b_j - x_a_j) * (s + 1) / 2;
                y_jk = y_a_j + (y_b_j - y_a_j) * (s + 1) / 2;

                % Distance from point i to current point on panel j
                dx = x_i - x_jk;
                dy = y_i - y_jk;
                dist_sq = dx^2 + dy^2;

                if dist_sq < 1e-12
                    u_contribution = 0;
                    v_contribution = 0;
                else
                    factor = gamma * w * (L_j / 2) / (2 * pi * dist_sq);
                    u_contribution = -dy * factor;
                    v_contribution = dx * factor;
                end

                u_ind = u_ind + u_contribution;
                v_ind = v_ind + v_contribution;
            end
        end

        % Total velocity components
        u_total = u_ind + u_fs;
        v_total = v_ind + v_fs;

        % Tangential velocity
        Vt = u_total * tx + v_total * ty;

        % Pressure coefficient
        cp(i) = 1.0 - (Vt / Vinf)^2;
    end
end

function [Cl, Cl_analytical] = compute_cl(Vinf, gamma, panel_lengths, chord, alpha_deg)
    % Compute lift coefficient using Kutta-Joukowski theorem

    Gamma = gamma * sum(panel_lengths);
    Cl = (2 * Gamma) / (Vinf * chord);

    % Analytical solution for flat plate (thin airfoil theory)
    Cl_analytical = 2 * pi * deg2rad(alpha_deg);
end

function perform_accuracy_check()
    % Perform accuracy check with different panel numbers

    panel_numbers = [10, 20, 40, 80, 160];
    max_errors = [];

    fprintf('Performing accuracy check with different panel numbers...\n');

    for n_panels = panel_numbers
        % Generate a circular cylinder with n_panels
        theta = linspace(0, 2*pi, n_panels+1);
        x = cos(theta);
        y = sin(theta);
        points = [x' y'];

