            response.raise_for_status()
            soup = BeautifulSoup(response.text, 'html.parser')
            spell_results = soup.find_all('div', class_='BNeawe vvjwJb AP7Wnd')
            if spell_results:
                return spell_results[0].text
        except requests.RequestException as e:
