                for (const auto& [target_id, weight] : neuron.outputs) {
                    neurons[target_id].receive_input(weight);
                }
            }
        }
        auto end_propagate = std::chrono::high_resolution_clock::now();
        std::chrono::duration<double> propagate_duration = end_propagate - start_propagate;
        std::cout << "Propagate time: " << propagate_duration.count() << " seconds" << std::endl;

        // Update the state of each neuron in parallel
        auto start_update = std::chrono::high_resolution_clock::now();
        for (int i = 0; i < num_threads; ++i) {
            threads[i] = std::thread([&, i, num_threads, t, dt]() {
                size_t start = i * neurons.size() / num_threads;
                size_t end = (i + 1) * neurons.size() / num_threads;
                for (size_t j = start; j < end; ++j) {
                    neurons[j].update(dt, neurons[j].external_input, t);
                }
            });
        }
        for (auto& thread : threads) {
            thread.join();
        }
        auto end_update = std::chrono::high_resolution_clock::now();
        std::chrono::duration<double> update_duration = end_update - start_update;
        std::cout << "Update time: " << update_duration.count() << " seconds" << std::endl;

        // Print the state of the neurons (for debugging)
        for (size_t i = 0; i < neurons.size(); ++i) {
            std::cout << "Neuron " << i << ": v = " << neurons[i].get_v() << ", spike = " << neurons[i].has_spiked() << std::endl;
        }
    }
}

// Function to measure memory usage
void measure_memory_usage() {
    struct rusage rusage;
    getrusage(RUSAGE_SELF, &rusage);
    long memory_usage_kb = rusage.ru_maxrss;
    std::cout << "Memory usage: " << memory_usage_kb << " KB" << std::endl;
}

int main() {
    // Create a network of 5 neurons
    std::vector<Neuron> neurons(5, Neuron(0.02, 0.2, -65, 8, -65, -13));

    // Connect the neurons randomly
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<> dis(0.0, 1.0);

    for (int i = 0; i < neurons.size(); ++i) {
        for (int j = 0; j < neurons.size(); ++j) {
            if (i != j && dis(gen) < 0.5) {
                neurons[i].connect(j, dis(gen));
            }
        }
    }

    // Measure initial memory usage
    measure_memory_usage();

    // Simulate the network
    auto start_sim = std::chrono::high_resolution_clock::now();
    simulate_network_parallel(neurons, 0.1, 100, 4);
    auto end_sim = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> sim_duration = end_sim - start_sim;
    std::cout << "Total simulation time: " << sim_duration.count() << " seconds" << std::endl;

    // Measure final memory usage
    measure_memory_usage();

    return 0;
}
```

### Explanation of the Code

1. **Memory Usage Measurement**:
   - **measure_memory_usage**: This function uses the `getrusage` function to measure the maximum resident set size (RSS) of the process, which gives an estimate of the memory usage in kilobytes.
   - **Measure Initial and Final Memory Usage**: The memory usage is measured before and after the simulation to identify any memory leaks or excessive memory consumption.

2. **Computational Efficiency Measurement**:
   - **High-Resolution Timers**: The `std::chrono::high_resolution_clock` is used to measure the execution time of different parts of the simulation (reset, propagate, and update steps).
   - **Print Execution Times**: The execution times are printed to the console to identify which parts of the simulation are taking the most time.

3. **Synchronization Overhead Measurement**:
   - **Thread Synchronization**: The `std::mutex` is used to ensure thread safety when modifying shared data structures.
   - **Profile Synchronization Overhead**: The execution times of the reset, propagate, and update steps can help identify the impact of synchronization overhead. If these times are significantly longer than expected, it may indicate that synchronization is a bottleneck.

By implementing these profiling and benchmarking methods, you can identify and address performance bottlenecks in large-scale networks, ensuring that the simulation runs efficiently and effectively.

