import webbrowser
import os

def generate_threejs_plot():
    """
    Generates an HTML file containing Three.js code to plot 3D functions.
    The script then opens this file in the default web browser.
    """

    html_template = """
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Three.js 3D Function Plotter</title>
    <style>
        body { margin: 0; overflow: hidden; font-family: sans-serif; }
        #ui { position: absolute; top: 10px; left: 10px; background: rgba(255,255,255,0.8); padding: 10px; border-radius: 5px; }
        canvas { display: block; }
    </style>
</head>
<body>
    <div id="ui">
        <label>Select Function:</label>
        <select id="funcSelect">
            <option value="paraboloid">Hyperbolic Paraboloid (z = x² - y²)</option>
            <option value="cone">Cone (z = √(x² + y²))</option>
        </select>
        <p><small>Use Mouse to Rotate/Zoom</small></p>
    </div>

    <!-- Load Three.js and OrbitControls via CDN -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
        import { ParametricGeometry } from 'three/addons/geometries/ParametricGeometry.js';

        // 1. Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0xf0f0f0);

        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(2, 2, 2);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);

        // 2. Mouse Controls (Rotate and Scale)
        const controls = new OrbitControls(camera, renderer.domElement);

        // 3. Axis Helper (Red: X, Green: Y, Blue: Z)
        const axesHelper = new THREE.AxesHelper(1.5);
        scene.add(axesHelper);

        // 4. Reference Plane (at z=0)
        // Note: In Three.js, the default "up" is Y. We will treat Y as the Z-axis for the math.
        const gridHelper = new THREE.GridHelper(2, 20); // 2x2 size, 20 divisions (0.1 increments)
        scene.add(gridHelper);

        // 5. Function Definitions
        // ParametricGeometry provides u, v in range [0, 1]. 
        // We map these to x, y in range [-1, 1].
        const segments = 20; // This creates increments of 0.1 (Range 2 / 20 = 0.1)

        const getHyperbolicParaboloid = (u, v, target) => {
            const x = (u - 0.5) * 2;
            const y = (v - 0.5) * 2;
            const z = (x * x) - (y * y);
            target.set(x, z, y); // Mapping math-Z to Three.js-Y (up)
        };

        const getCone = (u, v, target) => {
            const x = (u - 0.5) * 2;
            const y = (v - 0.5) * 2;
            const z = Math.sqrt(x * x + y * y);
            target.set(x, z, y);
        };

        // 6. Mesh Generation Logic
        let currentMesh;
        const material = new THREE.MeshPhongMaterial({
            color: 0x3498db,
            side: THREE.DoubleSide,
            wireframe: false,
            flatShading: false,
            transparent: true,
            opacity: 0.8
        });

        // Add wireframe to see the "mesh" grid
        const wireMaterial = new THREE.MeshBasicMaterial({ color: 0x000000, wireframe: true, transparent: true, opacity: 0.3 });

        function updatePlot(funcType) {
            if (currentMesh) scene.remove(currentMesh);

            const func = funcType === 'cone' ? getCone : getHyperbolicParaboloid;
            const geometry = new ParametricGeometry(func, segments, segments);

            currentMesh = new THREE.Group();
            currentMesh.add(new THREE.Mesh(geometry, material));
            currentMesh.add(new THREE.Mesh(geometry, wireMaterial));

            scene.add(currentMesh);
        }

        // 7. Lighting
        const light = new THREE.DirectionalLight(0xffffff, 1);
        light.position.set(5, 5, 5);
        scene.add(light);
        scene.add(new THREE.AmbientLight(0x404040));

        // Initial Plot
        updatePlot('paraboloid');

        // UI Listener
        document.getElementById('funcSelect').addEventListener('change', (e) => {
            updatePlot(e.target.value);
        });

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }

        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
    """

    # Write the HTML content to a file
    file_path = os.path.abspath("threejs_plot.html")
    with open(file_path, "w") as f:
        f.write(html_template)

    # Open the file in the web browser
    print(f"Opening visualization: {file_path}")
    webbrowser.open(f"file://{file_path}")

if __name__ == "__main__":
    generate_threejs_plot()
