    except (ValueError, TypeError):
        return credit, remaining_balance, False

    # Calculate new amount based on remaining balance
    if remaining_balance >= credit.open_balance:
        new_amount = str(credit.open_balance)
        new_remaining = remaining_balance - credit.open_balance
    elif remaining_balance > 0:
        new_amount = str(remaining_balance)
        new_remaining = 0
    else:
        new_amount = ""
        new_remaining = remaining_balance

    # Check if update is needed
    if credit.linked_payment_amount == new_amount:
        return credit, new_remaining, False

    # Create updated credit
    updated_credit = CreditChargesPayment(
        txn_id=credit.txn_id,
        open_balance=credit.open_balance,
        linked_payment_amount=new_amount
    )

    return updated_credit, new_remaining, True

def outstanding_transactions_handler_optimized() -> StepResponse:
    """
    Optimized version with reduced redundant validations and simplified logic.

    Key optimizations:
    1. Single validation and processing pass per credit
    2. Early filtering of invalid credits
    3. Minimal branching in main logic
    4. Reduced function calls and object creation

    Returns:
        StepResponse: Result of the operation
    """
    try:
        # Get data
        credit_table_lines = PaymentTableSelectors.get_credits()
        total_charges = PaymentTableSelectors.get_total_of_charges_table()

        # Basic input validation
        if not isinstance(credit_table_lines, list):
            return StepResponse(result=ResultType.FAILURE)

        if not isinstance(total_charges, (int, float)) or total_charges < 0:
            return StepResponse(result=ResultType.FAILURE)

        # Early return for empty data
        if not credit_table_lines or total_charges <= 0:
            PaymentChargesTableAction.full_credits_table_update([])
            return StepResponse(result=ResultType.SUCCESS)

        # Process all credits in a single optimized loop
        remaining_balance = float(total_charges)
        updated_credits: List[CreditChargesPayment] = []
        has_updates = False

        for credit in credit_table_lines:
            # Process credit in one function call
            result, remaining_balance, was_updated = validate_and_process_credit(
                credit, remaining_balance
            )

            if result is None:
                # Invalid credit - skip it entirely
                continue

            updated_credits.append(result)
            if was_updated:
                has_updates = True

        # Dispatch update if we have valid credits
        if updated_credits and has_updates:
            PaymentChargesTableAction.full_credits_table_update(updated_credits)

        return StepResponse(result=ResultType.SUCCESS)

    except Exception as e:
        print(f"Error processing transactions: {e}")
        return StepResponse(result=ResultType.FAILURE)


# Alternative: Even more simplified version for common cases
def outstanding_transactions_handler_simple() -> StepResponse:
    """
    Simplified version assuming data is mostly valid.
    Use when you trust the data source and want maximum performance.
    """
    try:
        credit_table_lines = PaymentTableSelectors.get_credits()
        total_charges = PaymentTableSelectors.get_total_of_charges_table()

        # Quick validation
        if not credit_table_lines or total_charges <= 0:
            PaymentChargesTableAction.full_credits_table_update([])
            return StepResponse(result=ResultType.SUCCESS)

        remaining_balance = float(total_charges)
        updated_credits = []
        has_updates = False

        for credit in credit_table_lines:
            # Assume data is valid - minimal validation
            linked_amount = credit.linked_payment_amount.strip()
            if not linked_amount:
                updated_credits.append(credit)
                continue

            # Calculate new amount
            if remaining_balance >= credit.open_balance:
                new_amount = str(credit.open_balance)
                remaining_balance -= credit.open_balance
            elif remaining_balance > 0:
                new_amount = str(remaining_balance)
                remaining_balance = 0
            else:
                new_amount = ""

            # Update if changed
            if credit.linked_payment_amount != new_amount:
                has_updates = True
                updated_credit = CreditChargesPayment(
                    txn_id=credit.txn_id,
                    open_balance=credit.open_balance,
                    linked_payment_amount=new_amount
                )
                updated_credits.append(updated_credit)
            else:
                updated_credits.append(credit)

        if has_updates:
            PaymentChargesTableAction.full_credits_table_update(updated_credits)

        return StepResponse(result=ResultType.SUCCESS)

    except Exception as e:
        print(f"Error: {e}")
        return StepResponse(result=ResultType.FAILURE)


