    /// <summary>
    /// nanoCAD command handler demonstrating table interaction.
    /// </summary>
    public class CommandHandlers
    {
        [CommandMethod("EmbedTest")]
        public void EmbedTest()
        {
            Document doc = Application.DocumentManager.MdiActiveDocument;
            Database db = doc.Database;
            Editor ed = doc.Editor;

            using (Transaction tr = db.TransactionManager.StartTransaction())
            {
                try
                {
                    // 1. Select target table
                    PromptEntityOptions peo = new PromptEntityOptions("Select table");
                    peo.SetRejectMessage("Must be a table");
                    peo.AddAllowedClass(typeof(McTable), true);

                    PromptEntityResult per = ed.GetEntity(peo);
                    if (per.Status != PromptStatus.OK)
                        return;

                    McTable table = (McTable)tr.GetObject(per.ObjectId, OpenMode.ForWrite);

                    // 2. Create geometry to embed
                    BlockTable bt = (BlockTable)tr.GetObject(db.BlockTableId, OpenMode.ForRead);
                    BlockTableRecord btr = (BlockTableRecord)tr.GetObject(
                        bt[BlockTableRecord.ModelSpace], OpenMode.ForWrite);

                    List<EntityGeometry> entities = new List<EntityGeometry>();

                    // Create a sample line
                    Line line = new Line(
                        new Point3d(0, 0, 0), 
                        new Point3d(50, 50, 0));
                    line.SetDatabaseDefaults();
                    btr.AppendEntity(line);
                    tr.AddNewlyCreatedDBObject(line, true);
                    entities.Add(line);

                    // 3. Embed into table cell (0,0)
                    table.EmbedPrimitivesToTableCell(0, 0, entities);

                    tr.Commit();
                    ed.WriteMessage("Successfully embedded geometry into table cell!");
                }
                catch (Exception ex)
                {
                    ed.WriteMessage($"\nError: {ex.Message}");
                    throw;
                }
            }
        }
    }
}
