                case 'clickElement':
                    this.clickElement(data.selector);
                    break;
            }
        }

        bringToFront() {
            // Try to bring window to front (limited by browser security)
            window.focus();

            // Additional methods to gain focus
            if (window.document.hasFocus()) {
                return true;
            }

            // Try to gain focus through user interaction simulation
            const focusAttempt = () => {
                const fakeBtn = document.createElement('button');
                fakeBtn.style.position = 'fixed';
                fakeBtn.style.top = '-100px';
                document.body.appendChild(fakeBtn);
                fakeBtn.focus();
                fakeBtn.remove();
            };

            try {
                focusAttempt();
            } catch (e) {
                console.log('Focus attempt failed:', e);
            }

            return window.document.hasFocus();
        }

        createNewTab(url) {
            const newTab = window.open(url, '_blank');
            if (newTab) {
