import numpy as np
from typing import List, Optional
import math

def determinant_optimized(matrix: List[List[float]], method: str = 'auto') -> float:
    """
    Optimized determinant calculation with multiple algorithm choices.

    Args:
        matrix: A 2D list representing a square matrix
        method: 'recursive', 'lu', 'numpy', or 'auto' for automatic selection

    Returns:
        The determinant value

    Raises:
        ValueError: If matrix is not square or invalid
    """
    n = len(matrix)

    # Validate matrix
    if n == 0:
        raise ValueError("Matrix cannot be empty")

    for i in range(n):
        if len(matrix[i]) != n:
            raise ValueError(f"Matrix must be square. Row {i} has {len(matrix[i])} columns, expected {n}")

    # Auto-select method based on matrix size
    if method == 'auto':
        if n <= 4:
            method = 'recursive'  # Small matrices
        elif n <= 100:
            method = 'lu'  # Medium matrices
        else:
            method = 'numpy'  # Large matrices

    # Dispatch to appropriate method
    if method == 'recursive':
        return _determinant_recursive(matrix)
    elif method == 'lu':
        return _determinant_lu(matrix)
    elif method == 'numpy':
        return _determinant_numpy(matrix)
    else:
        raise ValueError(f"Unknown method: {method}")


def _determinant_recursive(matrix: List[List[float]]) -> float:
    """
    Recursive determinant calculation (good for small matrices).
    """
    n = len(matrix)

    # Base cases
    if n == 1:
        return matrix[0][0]
    elif n == 2:
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]
    elif n == 3:
        # Sarrus' rule for 3x3 (more efficient than recursion)
        a, b, c = matrix[0]
        d, e, f = matrix[1]
        g, h, i = matrix[2]
        return (a*e*i + b*f*g + c*d*h) - (c*e*g + b*d*i + a*f*h)

    # Recursive case for n > 3
    det = 0.0

    # Choose the row/column with most zeros for efficiency
    row_with_most_zeros = 0
    max_zeros = 0
    for i in range(n):
        zeros = sum(1 for x in matrix[i] if abs(x) < 1e-12)
        if zeros > max_zeros:
            max_zeros = zeros
            row_with_most_zeros = i

    # Expand along the row with most zeros
    for j in range(n):
        if abs(matrix[row_with_most_zeros][j]) < 1e-12:
            continue  # Skip zero elements

        # Create minor matrix efficiently
        minor_mat = []
        for i in range(n):
            if i == row_with_most_zeros:
                continue
            row = []
            for k in range(n):
                if k != j:
                    row.append(matrix[i][k])
            minor_mat.append(row)

        # Compute cofactor
        sign = 1 if (row_with_most_zeros + j) % 2 == 0 else -1
        det += sign * matrix[row_with_most_zeros][j] * _determinant_recursive(minor_mat)

    return det


def _determinant_lu(matrix: List[List[float]]) -> float:
    """
    Determinant using LU decomposition with partial pivoting (O(n³)).
    """
    n = len(matrix)

    # Convert to numpy array
    A = np.array(matrix, dtype=float)

    # Initialize matrices
    U = A.copy()
    L = np.eye(n, dtype=float)
    P = np.eye(n, dtype=float)  # Permutation matrix

    # Perform LU decomposition with partial pivoting
    for k in range(n-1):
        # Find pivot
        pivot_row = k + np.argmax(np.abs(U[k:, k]))

        if pivot_row != k:
            # Swap rows in U
            U[[k, pivot_row], k:] = U[[pivot_row, k], k:]

            # Swap rows in L (only columns < k)
            if k > 0:
                L[[k, pivot_row], :k] = L[[pivot_row, k], :k]

            # Update permutation matrix
            P[[k, pivot_row]] = P[[pivot_row, k]]

        # Check for zero pivot (singular matrix)
        if abs(U[k, k]) < 1e-12:
            return 0.0

        # Compute multipliers and update
        for i in range(k+1, n):
            L[i, k] = U[i, k] / U[k, k]
            U[i, k:] -= L[i, k] * U[k, k:]

    # Determinant = product of diagonal of U * sign of permutation
    det = np.prod(np.diag(U))

    # Account for row swaps
    # Count swaps by checking permutation matrix
    swaps = 0
    for i in range(n):
        if P[i, i] == 0:
            # Find where 1 is in this row
            j = np.argmax(P[i])
            if j != i:
                swaps += 1

    if swaps % 2 == 1:
        det = -det

    return float(det)


def _determinant_numpy(matrix: List[List[float]]) -> float:
    """
    Determinant using NumPy's optimized LAPACK routines.
    """
    return float(np.linalg.det(matrix))


def minor_determinant_optimized(matrix: List[List[float]], row: int, col: int, 
                               method: str = 'auto') -> float:
    """
    Optimized minor determinant calculation.

    Args:
        matrix: A D list representing the matrix
        row: Row index to remove (0-based)
        col: Column index to remove (0-based)
        method: Method for determinant calculation

    Returns:
        The determinant of the minor matrix
    """
    n = len(matrix)

    # Validate indices
    if row < 0 or row >= n or col < 0 or col >= n:
        raise ValueError(f"Indices out of bounds. Matrix is {n}x{n}")

    # Handle edge cases
    if n == 1:
        return 1.0  # By convention

    # For 2x2 matrix, compute directly
    if n == 2:
        return matrix[1-row][1-col]

    # For larger matrices, use efficient numpy approach if available
    if method in ['numpy', 'auto'] and n > 4:
        A = np.array(matrix, dtype=float)

        # Create indices for rows and columns to keep
        rows_to_keep = [i for i in range(n) if i != row]
        cols_to_keep = [j for j in range(n) if j != col]

        # Extract submatrix efficiently
        minor_submatrix = A[np.ix_(rows_to_keep, cols_to_keep)]

        # Compute determinant
        return float(np.linalg.det(minor_submatrix))

    # Otherwise, create minor matrix and compute determinant
    minor_mat = []
    for i in range(n):
        if i == row:
            continue
        minor_mat.append(matrix[i][:col] + matrix[i][col+1:])

    return determinant_optimized(minor_mat, method)


