def optimized_minor_determinant(matrix: List[List[float]], row: int, col: int, 
                               use_numpy: bool = True) -> float:
    """
    Optimized minor determinant calculation for larger matrices.

    Args:
        matrix: Square matrix as 2D list
        row: Row to remove (0-based)
        col: Column to remove (0-based)
        use_numpy: Use NumPy for large matrices (recommended)

    Returns:
        Determinant of the minor matrix

    Raises:
        ValueError: For invalid inputs
    """
    # Input validation
    if not matrix:
        raise ValueError("Matrix cannot be empty")

    n = len(matrix)

    # Check if square
    for i in range(n):
        if len(matrix[i]) != n:
            raise ValueError(f"Matrix must be square. Row {i} has {len(matrix[i])} columns")

    # Check indices
    if row < 0 or row >= n or col < 0 or col >= n:
        raise ValueError(f"Indices out of bounds. Matrix is {n}x{n}")

    # Edge cases
    if n == 1:
        return 1.0  # Convention: determinant of empty matrix is 1

    if n == 2:
        # Direct calculation for 2x2
        return matrix[1-row][1-col]

    # For large matrices, use NumPy for efficiency
    if use_numpy and n > 4:
        A = np.array(matrix, dtype=float)

        # Create indices for rows/columns to keep
        rows_to_keep = [i for i in range(n) if i != row]
        cols_to_keep = [j for j in range(n) if j != col]

        # Extract submatrix efficiently using NumPy's advanced indexing
        minor_submatrix = A[np.ix_(rows_to_keep, cols_to_keep)]

        # Compute determinant using NumPy's optimized LAPACK routines
        return float(np.linalg.det(minor_submatrix))

    # For small matrices or when NumPy is not available
    # Create minor matrix efficiently using slicing
    minor_mat = []
    for i in range(n):
        if i == row:
            continue
        # Efficient slicing to skip the column
        minor_mat.append(matrix[i][:col] + matrix[i][col+1:])

    # Compute determinant recursively for small matrices
    return determinant_optimized_recursive(minor_mat)


def determinant_optimized_recursive(matrix: List[List[float]]) -> float:
    """
    Highly optimized recursive determinant calculation for small matrices (n ≤ 10).

    Key optimizations:
    1. Pre-allocated memory reuse for minor matrices
    2. Early zero detection and skipping
    3. Optimized base cases with direct formulas
    4. Row selection with most zeros
    5. Cache-friendly memory access patterns
    6. Reduced function call overhead

    Time Complexity: O(n!) worst case, but optimized for practical small matrices
    Space Complexity: O(n²) for buffer allocation
    """
    n = len(matrix)

    # Optimized base cases with direct formulas
    if n == 1:
        return matrix[0][0]

    if n == 2:
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]

    if n == 3:
        # Sarrus' rule - optimized for 3x3
        a, b, c = matrix[0]
        d, e, f = matrix[1]
        g, h, i = matrix[2]
        return (a*e*i + b*f*g + c*d*h) - (c*e*g + b*d*i + a*f*h)

    if n == 4:
        # Optimized 4x4 determinant using Laplace expansion
        # This reduces recursive depth and improves performance
        m00, m01, m02, m03 = matrix[0]
        m10, m11, m12, m13 = matrix[1]
        m20, m21, m22, m23 = matrix[2]
        m30, m31, m32, m33 = matrix[3]

        # Compute using cofactor expansion with pre-computed 3x3 determinants
        det = (m00 * (m11*(m22*m33 - m23*m32) - m12*(m21*m33 - m23*m31) + m13*(m21*m32 - m22*m31))
               - m01 * (m10*(m22*m33 - m23*m32) - m12*(m20*m33 - m23*m30) + m13*(m20*m32 - m22*m30))
               + m02 * (m10*(m21*m33 - m23*m31) - m11*(m20*m33 - m23*m30) + m13*(m20*m31 - m21*m30))
               - m03 * (m10*(m21*m32 - m22*m31) - m11*(m20*m32 - m22*m30) + m12*(m20*m31 - m21*m30)))
        return det

    # For n > 4, find row with most zeros for efficiency
    best_row = 0
    max_zeros = 0
    for i in range(n):
        zeros = 0
        row_data = matrix[i]
        for j in range(n):
            if abs(row_data[j]) < 1e-12:
                zeros += 1
        if zeros > max_zeros:
            max_zeros = zeros
            best_row = i

    # Pre-allocate memory for minor matrix to avoid repeated allocations
    minor_size = n - 1
    minor_mat = [[0.0] * minor_size for _ in range(minor_size)]

    det = 0.0
    best_row_data = matrix[best_row]

    # Expand along the best row
    for j in range(n):
        element = best_row_data[j]
        if abs(element) < 1e-12:
            continue  # Skip zero elements

        # Build minor matrix efficiently with cache-friendly access
        minor_i = 0
        for i in range(n):
            if i == best_row:
                continue

            row_i = matrix[i]
            minor_j = 0
            for k in range(n):
                if k == j:
                    continue
                minor_mat[minor_i][minor_j] = row_i[k]
                minor_j += 1
            minor_i += 1

        # Compute cofactor
        sign = 1 if (best_row + j) % 2 == 0 else -1
        det += sign * element * determinant_optimized_recursive(minor_mat)

    return det


