            }
            // Handle PNG compression (quality parameter not applicable)
            else
            {
                image.Save(ms, ImageFormat.Png);
            }

            byte[] imageBytes = ms.ToArray();

            // Apply size constraint if specified
            if (maxSizeKB > 0)
            {
                imageBytes = ConstrainImageSize(imageBytes, format, maxSizeKB, quality);
            }

            return imageBytes;
        }
    }

    /// <summary>
