    /// </summary>
    private static byte[] ConstrainImageSize(byte[] imageBytes, ImageFormat format, int maxSizeKB, int initialQuality)
    {
        int maxBytes = maxSizeKB * 1024;

        // If already under limit, return as-is
        if (imageBytes.Length <= maxBytes)
            return imageBytes;

        // For JPEG, we can reduce quality iteratively
        if (format == ImageFormat.Jpeg)
        {
            using (MemoryStream ms = new MemoryStream(imageBytes))
            using (Image image = Image.FromStream(ms))
            {
                int currentQuality = initialQuality;

                // Reduce quality until we meet size constraint or reach minimum quality
                while (imageBytes.Length > maxBytes && currentQuality > 10)
                {
                    currentQuality -= 5;

                    using (MemoryStream newMs = new MemoryStream())
                    {
                        ImageCodecInfo jpegCodec = GetEncoderInfo("image/jpeg");
                        EncoderParameters encoderParams = new EncoderParameters(1);
                        encoderParams.Param[0] = new EncoderParameter(Encoder.Quality, currentQuality);

                        image.Save(newMs, jpegCodec, encoderParams);
                        imageBytes = newMs.ToArray();
                    }
                }
            }
        }
        // For PNG, we could resize the image, but that's more complex
        // For simplicity, we'll just return the original if it's too large
        // In a production system, you might want to implement resizing

        return imageBytes;
    }

    /// <summary>
    /// Gets the image encoder for a specific MIME type
    /// </summary>
    private static ImageCodecInfo GetEncoderInfo(string mimeType)
    {
        ImageCodecInfo[] codecs = ImageCodecInfo.GetImageEncoders();

        foreach (ImageCodecInfo codec in codecs)
        {
            if (codec.MimeType == mimeType)
                return codec;
        }

        throw new NotSupportedException($"No encoder found for MIME type: {mimeType}");
