                encoderParams.Param[0] = new EncoderParameter(Encoder.Compression, 
                    options.CompressionLevel);

                // Color depth hint (helps with compression)
                encoderParams.Param[1] = new EncoderParameter(Encoder.ColorDepth, 
                    (long)(options.ReduceColors ? 24 : 32));

                workingImage.Save(ms, pngCodec, encoderParams);
                return ms.ToArray();
            }
        }
    }

    /// <summary>
    /// Converts 32-bit image to 24-bit (removes alpha channel)
    /// </summary>
    private static Bitmap ConvertTo24Bit(Bitmap image)
    {
        Bitmap result = new Bitmap(image.Width, image.Height, PixelFormat.Format24bppRgb);

        using (Graphics g = Graphics.FromImage(result))
        {
            g.DrawImage(image, 0, 0, image.Width, image.Height);
        }

        return result;
    }

    /// <summary>
    /// Applies Floyd-Steinberg dithering to reduce color banding
    /// </summary>
    private static Bitmap ApplyDithering(Bitmap image)
    {
        // Simplified dithering implementation
        // In production, consider using a more sophisticated dithering algorithm
        Bitmap result = new Bitmap(image);

        for (int y = 0; y < result.Height; y++)
        {
            for (int x = 0; x < result.Width; x++)
            {
                Color pixel = result.GetPixel(x, y);

                // Simple quantization
                int r = (pixel.R > 128) ? 255 : 0;
                int g = (pixel.G > 128) ? 255 : 0;
                int b = (pixel.B > 128) ? 255 : 0;

                result.SetPixel(x, y, Color.FromArgb(pixel.A, r, g, b));
            }
        }

        return result;
    }
}

