        /// <summary>
        /// Converts an image to byte array with compression options using ImageSharp
        /// </summary>
        public static async Task<byte[]> ConvertImageToByteArrayAsync(
            Stream imageStream, 
            string format, 
            int quality = 85, 
            int maxSizeKB = 0)
        {
            if (imageStream == null)
                throw new ArgumentNullException(nameof(imageStream));

            if (format.ToLower() != "jpeg" && format.ToLower() != "png")
                throw new ArgumentException("Only JPEG and PNG formats are supported", nameof(format));

            if (quality < 1 || quality > 100)
                throw new ArgumentOutOfRangeException(nameof(quality), "Quality must be between 1 and 100");

            // Reset stream position if needed
            if (imageStream.CanSeek)
                imageStream.Position = 0;

            using (var image = await Image.LoadAsync(imageStream))
            {
                byte[] result;

                if (format.ToLower() == "jpeg")
                {
                    var encoder = new JpegEncoder
                    {
                        Quality = quality,
                        ColorType = JpegColorType.YCbCrRatio420 // Better compression
                    };

                    using (var ms = new MemoryStream())
                    {
                        await image.SaveAsync(ms, encoder);
                        result = ms.ToArray();
                    }
                }
                else // PNG
                {
                    var encoder = new PngEncoder
                    {
                        CompressionLevel = PngCompressionLevel.BestCompression,
                        ColorType = PngColorType.RgbWithAlpha,
                        FilterMethod = PngFilterMethod.Adaptive,
                        InterlaceMethod = PngInterlaceMode.None
                    };

                    using (var ms = new MemoryStream())
                    {
                        await image.SaveAsync(ms, encoder);
                        result = ms.ToArray();
                    }
                }

                // Apply size constraint if specified
                if (maxSizeKB > 0)
                {
                    result = await ConstrainImageSizeAsync(image, format, maxSizeKB, quality, result);
                }

                return result;
            }
        }

        private static async Task<byte[]> ConstrainImageSizeAsync(
            Image image, 
            string format, 
            int maxSizeKB, 
            int initialQuality,
            byte[] currentBytes)
        {
            int maxBytes = maxSizeKB * 1024;

            if (currentBytes.Length <= maxBytes)
                return currentBytes;

            // For JPEG: Reduce quality iteratively
            if (format.ToLower() == "jpeg")
            {
                int currentQuality = initialQuality;

                while (currentBytes.Length > maxBytes && currentQuality > 10)
                {
                    currentQuality -= 5;

                    var encoder = new JpegEncoder
                    {
                        Quality = currentQuality,
                        ColorType = JpegColorType.YCbCrRatio420
                    };

                    using (var ms = new MemoryStream())
                    {
                        await image.SaveAsync(ms, encoder);
                        currentBytes = ms.ToArray();
                    }
                }
            }
            // For PNG: Multiple optimization strategies
            else
            {
                currentBytes = await OptimizePngSizeAsync(image, maxBytes, currentBytes);
            }

            return currentBytes;
        }

        private static async Task<byte[]> OptimizePngSizeAsync(
            Image image, 
            int maxBytes, 
            byte[] currentBytes)
        {
            // Strategy 1: Try different PNG compression settings
            var compressionLevels = new[]
            {
                PngCompressionLevel.BestCompression,
                PngCompressionLevel.DefaultCompression,
                PngCompressionLevel.NoCompression
            };

            foreach (var level in compressionLevels)
            {
                var encoder = new PngEncoder
                {
                    CompressionLevel = level,
                    ColorType = PngColorType.RgbWithAlpha,
                    FilterMethod = PngFilterMethod.Adaptive
                };

                using (var ms = new MemoryStream())
                {
                    await image.SaveAsync(ms, encoder);
                    var newBytes = ms.ToArray();

                    if (newBytes.Length <= maxBytes)
                        return newBytes;

                    // Keep the smallest version so far
                    if (newBytes.Length < currentBytes.Length)
                        currentBytes = newBytes;
                }
            }

            // Strategy 2: Reduce color depth if image has transparency
            if (HasTransparency(image))
            {
                // Convert to 24-bit RGB (remove alpha)
                image.Mutate(x => x.BackgroundColor(SixLabors.ImageSharp.Color.White));

                var encoder = new PngEncoder
                {
                    CompressionLevel = PngCompressionLevel.BestCompression,
                    ColorType = PngColorType.Rgb,
                    FilterMethod = PngFilterMethod.Adaptive
                };

                using (var ms = new MemoryStream())
                {
                    await image.SaveAsync(ms, encoder);
                    var newBytes = ms.ToArray();

                    if (newBytes.Length <= maxBytes)
                        return newBytes;

                    if (newBytes.Length < currentBytes.Length)
                        currentBytes = newBytes;
                }
            }

            // Strategy 3: Resize image proportionally
            return await ResizeImageToMeetSizeAsync(image, maxBytes);
        }

        private static async Task<byte[]> ResizeImageToMeetSizeAsync(
            Image image, 
            int maxBytes)
        {
            int originalWidth = image.Width;
            int originalHeight = image.Height;

            // Try different scale factors
            double[] scaleFactors = { 0.9, 0.75, 0.5, 0.25, 0.1 };

            foreach (var scale in scaleFactors)
            {
                int newWidth = (int)(originalWidth * scale);
                int newHeight = (int)(originalHeight * scale);

                if (newWidth < 10 || newHeight < 10)
                    continue;

                using (var resizedImage = image.Clone(x => x.Resize(newWidth, newHeight)))
                {
                    var encoder = new PngEncoder
                    {
                        CompressionLevel = PngCompressionLevel.BestCompression,
                        ColorType = PngColorType.RgbWithAlpha
                    };

                    using (var ms = new MemoryStream())
                    {
                        await resizedImage.SaveAsync(ms, encoder);
                        var newBytes = ms.ToArray();

                        if (newBytes.Length <= maxBytes)
                            return newBytes;
                    }
                }
            }

            // Return the smallest we could produce
            return await GetSmallestPngAsync(image);
        }

        private static async Task<byte[]> GetSmallestPngAsync(Image image)
        {
            var encoder = new PngEncoder
            {
                CompressionLevel = PngCompressionLevel.BestCompression,
                ColorType = PngColorType.Rgb,
                FilterMethod = PngFilterMethod.None
            };

            using (var ms = new MemoryStream())
            {
                await image.SaveAsync(ms, encoder);
                return ms.ToArray();
            }
        }

        private static bool HasTransparency(Image image)
        {
            // Check if image has alpha channel
            return image.PixelType.BitsPerPixel == 32;
        }
    }

