class Result:
    def __init__(self, is_ok, value=None, error=None):
        self.is_ok = is_ok
        self.value = value
        self.error = error

    @staticmethod
    def ok(value):
        return Result(True, value=value)

    @staticmethod
    def err(error):
        return Result(False, error=error)

def get_sym_json_path(args, region_json):
    def get_path(region):
        upper_region = region.upper()
        if upper_region in region_json['_Regions_']:
            return Result.ok(region_json['_Regions_'][upper_region])
        else:
            return Result.err(f"{region} not found in _Regions_")

    results = [get_path(region) for region in args['region']]

    # Collect the results into a single Result
    errors = [r.error for r in results if not r.is_ok]
    if errors:
        return Result.err("\n".join(errors))
    else:
        return Result.ok([r.value for r in results])

