function [public_key, private_key] = rsa_key_generator(key_size)
    % RSA_KEY_GENERATOR Generate RSA public and private keys
    %
    % Input:
    %   key_size - Bit length of RSA modulus (e.g., 1024, 2048)
    %
    % Output:
    %   public_key  - Structure with fields e and n
    %   private_key - Structure with fields d and n

    fprintf('Generating %d-bit RSA keys...\n', key_size);

    % ============================================
    % STEP 1: Generate two large prime numbers
    % ============================================

    half_bits = key_size / 2;

    % Generate first prime number
    fprintf('Generating first prime (p)... ');
    p = generate_large_prime(half_bits);
    fprintf('Done. p = %d-bit prime\n', floor(log2(p)) + 1);

    % Generate second prime number (different from first)
    fprintf('Generating second prime (q)... ');
    q = generate_large_prime(half_bits);
    while q == p
        q = generate_large_prime(half_bits);
    end
    fprintf('Done. q = %d-bit prime\n', floor(log2(q)) + 1);

    % ============================================
    % STEP 2: Compute RSA modulus and totient
    % ============================================

    n = p * q;              % RSA modulus
    phi_n = (p - 1) * (q - 1);  % Euler's totient function

    fprintf('RSA modulus n = p * q = %d bits\n', floor(log2(n)) + 1);

    % ============================================
    % STEP 3: Choose public exponent e
    % ============================================

    % Common choices: 65537 (0x10001) or 3
    % 65537 is preferred as it's a Fermat prime (2^16 + 1)
    e = 65537;

    % Ensure e is coprime with phi_n
    if gcd(e, phi_n) ~= 1
        % If not coprime, find a suitable e
        e = 3;
        while gcd(e, phi_n) ~= 1
            e = e + 2;  % Try odd numbers
        end
    end

    fprintf('Public exponent e = %d\n', e);

    % ============================================
    % STEP 4: Compute private exponent d
    % ============================================

    % d = e^(-1) mod phi_n
    % Using extended Euclidean algorithm
    [~, d, ~] = extended_gcd(e, phi_n);

    % Ensure d is positive
    d = mod(d, phi_n);

    fprintf('Private exponent d computed\n');

    % ============================================
    % STEP 5: Create key structures
    % ============================================

    public_key = struct('e', e, 'n', n);
    private_key = struct('d', d, 'n', n);

    % ============================================
    % STEP 6: Display key information
    % ============================================

    fprintf('\n=== KEY GENERATION COMPLETE ===\n');
    fprintf('Public Key:\n');
    fprintf('  e = %s\n', num2str(e));
    fprintf('  n = %s... (first 20 digits)\n', num2str(n, 20));

    fprintf('\nPrivate Key:\n');
    fprintf('  d = %s... (first 20 digits)\n', num2str(d, 20));
    fprintf('  n = %s... (first 20 digits)\n', num2str(n, 20));

    fprintf('\nKey size: %d bits\n', key_size);
    fprintf('Actual modulus size: %d bits\n', floor(log2(n)) + 1);
end

%% ============================================
%% File: generate_large_prime.m
%% ============================================

function prime = generate_large_prime(bits)
    % GENERATE_LARGE_PRIME Generate a large prime number
    %
    % Input:
    %   bits - Approximate bit length of prime
    %
    % Output:
    %   prime - A prime number of approximately 'bits' bits

    % MATLAB's isprime is efficient for large numbers
    % but we need to generate random numbers of specific bit length

    % Calculate approximate decimal range for desired bit length
    min_val = 2^(bits - 1);
    max_val = 2^bits - 1;

    % Generate random odd number in the range
    candidate = randi([min_val, max_val]);

    % Ensure it's odd
    if mod(candidate, 2) == 0
        candidate = candidate + 1;
        if candidate > max_val
            candidate = candidate - 2;
        end
    end

    % Find next prime (MATLAB's isprime is deterministic)
    while ~isprime(candidate)
        candidate = candidate + 2;
        % If we exceed max_val, wrap around
        if candidate > max_val
            candidate = min_val;
            if mod(candidate, 2) == 0
                candidate = candidate + 1;
            end
        end
    end

    prime = candidate;
end

%% ============================================
%% File: extended_gcd.m
%% ============================================

function [g, x, y] = extended_gcd(a, b)
    % EXTENDED_GCD Extended Euclidean Algorithm
    %
    % Input:
    %   a, b - Integers
    %
    % Output:
    %   g - gcd(a, b)
    %   x, y - Coefficients such that a*x + b*y = g

    if a == 0
        g = b;
        x = 0;
        y = 1;
    else
        [g, x1, y1] = extended_gcd(mod(b, a), a);
        x = y1 - floor(b / a) * x1;
        y = x1;
    end
end

