function save_rsa_keys(public_key, private_key, filename_prefix)
    % SAVE_RSA_KEYS Save RSA keys to MAT files
    %
    % Input:
    %   public_key  - Public key structure
    %   private_key - Private key structure
    %   filename_prefix - Prefix for saved files

    % Save public key
    public_filename = sprintf('%s_public.mat', filename_prefix);
    save(public_filename, 'public_key');
    fprintf('Public key saved to: %s\n', public_filename);

    % Save private key
    private_filename = sprintf('%s_private.mat', filename_prefix);
    save(private_filename, 'private_key');
    fprintf('Private key saved to: %s\n', private_filename);

    % Also save as text files for readability
    txt_public = sprintf('%s_public.txt', filename_prefix);
    fid = fopen(txt_public, 'w');
    fprintf(fid, 'RSA Public Key\n');
    fprintf(fid, '==============\n');
    fprintf(fid, 'e = %s\n', num2str(public_key.e));
    fprintf(fid, 'n = %s\n', num2str(public_key.n));
    fclose(fid);

    txt_private = sprintf('%s_private.txt', filename_prefix);
    fid = fopen(txt_private, 'w');
