function prime = generate_prime_good(bits)
    % GOOD PRACTICE: Secure prime generation
    % Reseed random number generator
    rng('shuffle');

    min_val = 2^(bits - 1);
    max_val = 2^bits - 1;

    % Generate random starting point
    candidate = randi([min_val, max_val], 1, 'uint64');

    % Ensure odd
