function strong = is_strong_prime(p)
    % Check if prime is strong (resistant to certain attacks)
    % A strong prime p satisfies:
    % 1. p-1 has a large prime factor r
    % 2. p+1 has a large prime factor s
    % 3. r-1 has a large prime factor t

    if ~isprime(p)
        strong = false;
        return;
    end

    % Check p-1 has large prime factor
    factors_p_minus_1 = factor(p-1);
    if length(factors_p_minus_1) < 2
        strong = false;
        return;
    end

    % Check p+1 has large prime factor
    factors_p_plus_1 = factor(p+1);
    if length(factors_p_plus_1) < 2
        strong = false;
        return;
    end

    strong = true;
end

function [success, factors] = fermat_factorization(n)
    % Fermat's factorization method
    % Works when p and q are close: n = a^2 - b^2

    a = ceil(sqrt(n));
    max_iterations = 1000;

    for i = 1:max_iterations
        b2 = a^2 - n;
        b = sqrt(b2);

        if b == floor(b)  % b is integer
            p = a + b;
            q = a - b;
            factors = [p, q];
            success = true;
            return;
        end

        a = a + 1;
    end

    factors = [];
    success = false;
end

