```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <chrono>
#include <random>
#include <iomanip>

using namespace std;
using namespace std::chrono;

// Node structure for Binary Search Tree
struct Node {
    int data;
    Node* left;
    Node* right;

    Node(int val) : data(val), left(nullptr), right(nullptr) {}
};

// Binary Search Tree class
class BST {
private:
    Node* root;

    // Helper function for recursive insertion
    Node* insertRecursive(Node* node, int key) {
        if (node == nullptr) {
            return new Node(key);
        }

        if (key < node->data) {
            node->left = insertRecursive(node->left, key);
        } else {
            node->right = insertRecursive(node->right, key);
        }

        return node;
    }

    // Helper function for inorder traversal
    void inorderRecursive(Node* node, vector<int>& result) {
        if (node != nullptr) {
            inorderRecursive(node->left, result);
            result.push_back(node->data);
            inorderRecursive(node->right, result);
        }
    }

    // Helper function to calculate tree height
    int heightRecursive(Node* node) {
        if (node == nullptr) {
            return 0;
        }
        return 1 + max(heightRecursive(node->left), heightRecursive(node->right));
    }

    // Helper function to delete tree (prevent memory leaks)
    void deleteTree(Node* node) {
        if (node != nullptr) {
            deleteTree(node->left);
            deleteTree(node->right);
            delete node;
        }
    }

public:
    BST() : root(nullptr) {}

    ~BST() {
        deleteTree(root);
    }

    // Insert a key into BST
    void insert(int key) {
        root = insertRecursive(root, key);
    }

    // Build balanced BST from sorted array
    Node* sortedArrayToBST(const vector<int>& arr, int start, int end) {
        if (start > end) {
            return nullptr;
        }

        int mid = start + (end - start) / 2;
        Node* node = new Node(arr[mid]);

        node->left = sortedArrayToBST(arr, start, mid - 1);
        node->right = sortedArrayToBST(arr, mid + 1, end);

        return node;
    }

    // Set root for balanced BST
    void setRoot(Node* newRoot) {
        deleteTree(root); // Clean up old tree
        root = newRoot;
    }

    // Get inorder traversal (returns sorted elements)
    vector<int> inorderTraversal() {
        vector<int> result;
        inorderRecursive(root, result);
        return result;
    }

    // Get tree height
    int getHeight() {
        return heightRecursive(root);
    }

    // Get root node
    Node* getRoot() const {
        return root;
    }
};

// Selection Sort Algorithm
void selectionSort(vector<int>& arr) {
    int n = arr.size();

    for (int i = 0; i < n - 1; i++) {
        // Find the minimum element in unsorted part
        int minIndex = i;
        for (int j = i + 1; j < n; j++) {
            if (arr[j] < arr[minIndex]) {
                minIndex = j;
            }
        }

        // Swap the found minimum element with the first element
        swap(arr[i], arr[minIndex]);
    }
}

// Function to create BST using Selection Sort
pair<BST, double> createBSTWithSelectionSort(vector<int> arr) {
    BST bst;

    // Time the selection sort
    auto start = high_resolution_clock::now();
    selectionSort(arr);
    auto stop = high_resolution_clock::now();
    double sortTime = duration_cast<microseconds>(stop - start).count() / 1000000.0;

    // Build balanced BST from sorted array
    start = high_resolution_clock::now();
    Node* root = bst.sortedArrayToBST(arr, 0, arr.size() - 1);
    bst.setRoot(root);
    stop = high_resolution_clock::now();
    double bstTime = duration_cast<microseconds>(stop - start).count() / 1000000.0;

    cout << "Selection Sort Time: " << fixed << setprecision(6) << sortTime << " seconds" << endl;
    cout << "Balanced BST Construction Time: " << bstTime << " seconds" << endl;
    cout << "Total Time: " << sortTime + bstTime << " seconds" << endl;

    return make_pair(bst, sortTime + bstTime);
}

// Function to create BST by direct insertion (for comparison)
pair<BST, double> createBSTDirectly(const vector<int>& arr) {
    BST bst;

    auto start = high_resolution_clock::now();
    for (int value : arr) {
        bst.insert(value);
    }
    auto stop = high_resolution_clock::now();
    double timeTaken = duration_cast<microseconds>(stop - start).count() / 1000000.0;

    cout << "Direct BST Insertion Time: " << fixed << setprecision(6) << timeTaken << " seconds" << endl;

    return make_pair(bst, timeTaken);
}

// Function to generate random array
vector<int> generateRandomArray(int size, int minVal = 1, int maxVal = 10000) {
    vector<int> arr(size);
    random_device rd;
    mt19937 gen(rd());
    uniform_int_distribution<> dis(minVal, maxVal);

    for (int i = 0; i < size; i++) {
        arr[i] = dis(gen);
    }

    return arr;
}

