            return False
        except MemoryError:
            print("Error: Memory allocation failed.")
            return False
        except Exception as e:
            print(f"Error building BST: {e}")
            return False

    def _build_balanced(self, arr: List[int], start: int, end: int) -> Optional[Node]:
        """Recursive balanced tree construction with overflow protection"""
        if start > end:
            return None

        # Safe midpoint calculation - prevents integer overflow
        mid = start + (end - start) // 2

        node = Node(arr[mid])
        node.left = self._build_balanced(arr, start, mid - 1)
        node.right = self._build_balanced(arr, mid + 1, end)

        return node

