        """Return values in sorted order"""
        result: List[int] = []
        self._inorder_traversal(self.root, result)
        return result

    def _inorder_traversal(self, node: Optional[Node], result: List[int]) -> None:
        """Inorder traversal helper"""
        if node:
            self._inorder_traversal(node.left, result)
            result.append(node.value)
            self._inorder_traversal(node.right, result)

    def get_height(self) -> int:
        """Calculate tree height"""
        return self._calculate_height(self.root)

    def _calculate_height(self, node: Optional[Node]) -> int:
        """Height calculation helper"""
        if node is None:
            return 0
        return 1 + max(self._calculate_height(node.left), 
                      self._calculate_height(node.right))

    def is_balanced(self) -> bool:
        """Check if tree is height-balanced"""
        return self._check_balance(self.root) != -1

    def _check_balance(self, node: Optional[Node]) -> int:
        """Return height if balanced, -1 if not"""
        if node is None:
            return 0

        left_height = self._check_balance(node.left)
        if left_height == -1:
            return -1

        right_height = self._check_balance(node.right)
        if right_height == -1:
            return -1

        if abs(left_height - right_height) > 1:
            return -1

        return 1 + max(left_height, right_height)

