// Binary Search Tree class with improved memory management
class BST {
private:
    unique_ptr<Node> root;
    size_t nodeCount;

    // Helper function for inorder traversal
    void inorderRecursive(const unique_ptr<Node>& node, vector<int>& result) const {
        if (node) {
            inorderRecursive(node->left, result);
            result.push_back(node->data);
            inorderRecursive(node->right, result);
        }
    }

    // Helper function to calculate tree height
    int heightRecursive(const unique_ptr<Node>& node) const {
        if (!node) {
            return 0;
        }
        return 1 + max(heightRecursive(node->left), heightRecursive(node->right));
    }

    // Helper function to build balanced BST from sorted array
    unique_ptr<Node> sortedArrayToBST(const vector<int>& arr, int start, int end) {
        // Base case: prevent infinite recursion
        if (start > end) {
            return nullptr;
        }

        // Safe midpoint calculation to prevent integer overflow
        int mid = start + (end - start) / 2;

        // Create node with middle element
        auto node = make_unique<Node>(arr[mid]);

        // Recursively build left and right subtrees
        node->left = sortedArrayToBST(arr, start, mid - 1);
        node->right = sortedArrayToBST(arr, mid + 1, end);

        return node;
    }

public:
    BST() : root(nullptr), nodeCount(0) {}

    // No need for destructor - unique_ptr handles cleanup automatically

    // Build balanced BST from sorted array with error checking
    bool buildFromSortedArray(const vector<int>& sortedArr) {
        if (sortedArr.empty()) {
            root = nullptr;
            nodeCount = 0;
            return true;
        }

        // Check for potential recursion depth issues
        if (sortedArr.size() > 10000) {
            cerr << "Warning: Building BST from " << sortedArr.size() 
                 << " elements may cause recursion depth issues" << endl;
        }

        try {
            nodeCount = sortedArr.size();
            root = sortedArrayToBST(sortedArr, 0, sortedArr.size() - 1);
            return true;
        } catch (const bad_alloc& e) {
            cerr << "Error: Memory allocation failed: " << e.what() << endl;
            return false;
        } catch (const exception& e) {
            cerr << "Error building BST: " << e.what() << endl;
            return false;
        }
    }

    // Get inorder traversal (returns sorted elements)
    vector<int> inorderTraversal() const {
        vector<int> result;
        result.reserve(nodeCount);
        inorderRecursive(root, result);
        return result;
    }

    // Get tree height
    int getHeight() const {
        return heightRecursive(root);
    }

    // Check if tree is balanced
    bool isBalanced() const {
        return checkBalance(root) != -1;
    }

    // Helper for balance checking
    int checkBalance(const unique_ptr<Node>& node) const {
        if (!node) {
            return 0;
        }

        int leftHeight = checkBalance(node->left);
        if (leftHeight == -1) {
            return -1;
        }

        int rightHeight = checkBalance(node->right);
        if (rightHeight == -1) {
            return -1;
        }

        if (abs(leftHeight - rightHeight) > 1) {
            return -1;
        }

        return 1 + max(leftHeight, rightHeight);
    }

    // Get number of nodes
    size_t getNodeCount() const {
        return nodeCount;
    }
};

// Selection Sort Algorithm with improvements
pair<vector<int>, bool> selectionSort(const vector<int>& arr) {
    if (arr.empty()) {
        return make_pair(vector<int>(), true);
    }

    // Performance warning for large arrays
    if (arr.size() > 10000) {
        cerr << "Warning: Selection sort on " << arr.size() 
             << " elements is O(n²)" << endl;
        cerr << "Expected operations: ~" << arr.size() * arr.size() << endl;
        cerr << "This will be very slow. Consider using a more efficient algorithm." << endl;

        // Ask for confirmation
        cout << "Continue anyway? (y/n): ";
        char response;
        cin >> response;
        if (response != 'y' && response != 'Y') {
            return make_pair(vector<int>(), false);
        }
    }

    try {
        vector<int> sortedArr = arr;
        size_t n = sortedArr.size();

        // Early optimization: check if already sorted
        bool isAlreadySorted = true;
        for (size_t i = 0; i < n - 1; ++i) {
            if (sortedArr[i] > sortedArr[i + 1]) {
                isAlreadySorted = false;
                break;
            }
        }

        if (isAlreadySorted) {
            cout << "Array is already sorted - skipping sort operations" << endl;
            return make_pair(sortedArr, true);
        }

        // Standard selection sort
        for (size_t i = 0; i < n - 1; ++i) {
            size_t minIdx = i;

            // Find minimum in unsorted portion
            for (size_t j = i + 1; j < n; ++j) {
                if (sortedArr[j] < sortedArr[minIdx]) {
                    minIdx = j;
                }
            }

            // Swap if needed
            if (minIdx != i) {
                swap(sortedArr[i], sortedArr[minIdx]);
            }
        }

        return make_pair(sortedArr, true);

    } catch (const bad_alloc& e) {
        cerr << "Error: Insufficient memory for sorting operation: " << e.what() << endl;
        return make_pair(vector<int>(), false);
    } catch (const exception& e) {
        cerr << "Unexpected error during sorting: " << e.what() << endl;
        return make_pair(vector<int>(), false);
    }
}

// Function to create BST using Selection Sort with comprehensive error handling
tuple<BST, double, double, bool> createBSTWithSelectionSort(const vector<int>& arr) {
    // Input validation
    if (arr.empty()) {
        cout << "Info: Empty array provided. Returning empty BST." << endl;
        return make_tuple(BST(), 0.0, 0.0, true);
    }

    cout << "Processing array of size " << arr.size() << "..." << endl;

    BST bst;

    // Step 1: Sort with selection sort
    auto sortStart = high_resolution_clock::now();
    auto [sortedArr, sortSuccess] = selectionSort(arr);
    auto sortEnd = high_resolution_clock::now();
    double sortTime = duration_cast<microseconds>(sortEnd - sortStart).count() / 1000000.0;

    if (!sortSuccess) {
        cerr << "Failed to sort array." << endl;
        return make_tuple(BST(), sortTime, 0.0, false);
    }

    // Step 2: Build balanced BST
    auto buildStart = high_resolution_clock::now();
    bool buildSuccess = bst.buildFromSortedArray(sortedArr);
    auto buildEnd = high_resolution_clock::now();
    double buildTime = duration_cast<microseconds>(buildEnd - buildStart).count() / 1000000.0;

    if (!buildSuccess) {
        cerr << "Failed to build BST." << endl;
        return make_tuple(BST(), sortTime, buildTime, false);
    }

    return make_tuple(move(bst), sortTime, buildTime, true);
}

