// Rust procedural macro with proper error handling
use proc_macro::TokenStream;
use syn::{parse_macro_input, DeriveInput, Error};
use quote::quote;
use proc_macro_error::{proc_macro_error, abort_call_site};

// Example 1: Basic error handling with syn::parse
#[proc_macro]
pub fn safe_macro(input: TokenStream) -> TokenStream {
    // Parse with error handling instead of unwrap/expect
    let parsed = match syn::parse::<syn::Expr>(input) {
        Ok(expr) => expr,
        Err(err) => {
            // Convert syn::Error to TokenStream for proper error reporting
            return err.to_compile_error().into();
        }
    };

    // Process the parsed expression
    let expanded = quote! {
        {
            let result = #parsed;
            println!("Evaluated to: {}", result);
            result
        }
    };

    expanded.into()
}

// Example 2: Using proc_macro_error crate for better error handling
use proc_macro_error::proc_macro_error;

#[proc_macro_attribute]
#[proc_macro_error]
pub fn validate_struct(_attr: TokenStream, item: TokenStream) -> TokenStream {
    // Parse the input as a DeriveInput
    let input = parse_macro_input!(item as DeriveInput);

    // Validate the struct has at least one field
    if let syn::Data::Struct(data) = &input.data {
        if data.fields.is_empty() {
            // Use proc_macro_error's abort! macro for better error messages
            abort_call_site!(
                "Struct must have at least one field";
                help = "Add one or more fields to your struct"
            );
        }

        // Validate field names don't start with underscore
        for field in &data.fields {
            if let Some(ident) = &field.ident {
                if ident.to_string().starts_with('_') {
                    abort_call_site!(
                        "Field names cannot start with underscore";
                        note = "Field '{}' violates this rule", ident;
                        help = "Rename the field without leading underscore"
                    );
                }
            }
        }
    } else {
        abort_call_site!("This macro only works on structs");
    }

    // Return the original item unchanged (validation passed)
    item
}

