#[proc_macro_error]
pub fn derive_validated(input: TokenStream) -> TokenStream {
    let input = parse_macro_input!(item as DeriveInput);

    let struct_name = &input.ident;
    let mut validation_checks = Vec::new();
    let mut error_messages = Vec::new();

