# First pass: Map transcripts to genes
$3 ~ /(mRNA|transcript|transcript_gene_segment)/ {
    split($9, a, ";"); 
    for (i in a) {
        if (a[i] ~ /^ID=/) { split(a[i], id, "="); tid=id[2] }
        if (a[i] ~ /^Parent=/) { split(a[i], p, "="); gid=p[2] }
    }
    t2g[tid] = gid;
}
# Second pass: Count exons using the map
$3 == "exon" {
    split($9, a, ";");
    for (i in a) {
        if (a[i] ~ /^Parent=/) {
            split(a[i], p, "=");
            parent = p[2];
            # If parent is a transcript, get the gene. Otherwise use parent directly.
            gene = (parent in t2g) ? t2g[parent] : parent;
            count[gene]++;
        }
    }
}
