void dijkstra(int src, long long dist[]) {
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;
    memset(dist, -1, sizeof(long long) * (n + 1));
    dist[src] = 0;
    pq.push({0, src});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();

        if (dist[u] != d) continue;

        for (auto [v, w] : adj[u]) {
            if (dist[v] == -1 || dist[v] > dist[u] + w) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> n >> m >> k;

    for (int i = 0; i < m; ++i) {
        int u, v, w;
        cin >> u >> v >> w;
        adj[u].emplace_back(v, w);
        adj[v].emplace_back(u, w);
    }

    dijkstra(1, dist1);
    dijkstra(n, distn);

    // Precompute the minimum waiting time for each possible meeting point
    vector<pair<long long, int>> waiting_times;
    for (int j = 1; j <= n; ++j) {
        long long time_thuan = dist1[j];
        long long time_dong = distn[j];
        long long wait_time = max(time_thuan, time_dong) - min(time_thuan, time_dong);
        waiting_times.push_back({wait_time, j});
    }

    // Sort the waiting times to quickly find the minimum waiting time for each day
    sort(waiting_times.begin(), waiting_times.end());

    for (int i = 0; i < k; ++i) {
        int a, b;
        cin >> a >> b;
        long long min_wait_time = INF;
        int best_meeting_point = -1;

        for (auto [wait_time, meeting_point] : waiting_times) {
            long long time_thuan = dist1[meeting_point] * a;
            long long time_dong = distn[meeting_point] * b;
            long long current_wait_time = max(time_thuan, time_dong) - min(time_thuan, time_dong);

            if (current_wait_time < min_wait_time) {
                min_wait_time = current_wait_time;
                best_meeting_point = meeting_point;
            }

            if (min_wait_time == 0) {
                break;
            }
        }

        cout << min_wait_time << '\n';
    }

    return 0;
}
```

### Explanation:

1. **Graph Representation**:
   - We use an adjacency list to represent the graph. Each edge is stored as a pair `(v, w)` where `v` is the destination vertex and `w` is the weight of the edge.

2. **Dijkstra's Algorithm**:
   - We run Dijkstra's algorithm twice: once from node 1 (Thuan's starting point) and once from node n (Dong's starting point). This gives us the shortest distances from these points to all other nodes in the graph.

3. **Precompute Waiting Times**:
   - We precompute the waiting time for each possible meeting point and store it in a vector of pairs `(waiting_time, meeting_point)`.
   - We sort this vector to quickly find the minimum waiting time for each day.

4. **Input Reading**:
   - We read the number of places, roads, and days.
   - We read the edges and store them in the adjacency list.
   - We read the speeds for each day.

5. **Finding the Optimal Meeting Point**:
   - For each day, we iterate through the sorted vector of waiting times and calculate the actual waiting time for each meeting point.
   - We choose the meeting point that minimizes the waiting time.

6. **Output**:
   - We output the minimum waiting time for each day, one integer per line.

