    Color color = NONE;
};

class ChessEngine {
public:
    Piece board[8][8];
    Color currentTurn = WHITE;

    ChessEngine() { resetBoard(); }

    void resetBoard() {
        // Simplified initialization for demonstration
        for(int i=0; i<8; i++) {
            board[1][i] = {PAWN, BLACK};
            board[6][i] = {PAWN, WHITE};
        }
        board[0][0] = board[0][7] = {ROOK, BLACK};
        board[7][0] = board[7][7] = {ROOK, WHITE};
        currentTurn = WHITE;
    }

    bool movePiece(int x1, int y1, int x2, int y2) {
        // Basic move logic (validation would be expanded here)
        if (board[y1][x1].color == currentTurn) {
            board[y2][x2] = board[y1][x1];
            board[y1][x1] = {EMPTY, NONE};
            currentTurn = (currentTurn == WHITE) ? BLACK : WHITE;
            return true;
        }
        return false;
    }
};

