            return paramiko.AUTH_SUCCESSFUL
        logger.warning(f"Failed authentication attempt from {self.client_ip} as {username}")
        return paramiko.AUTH_FAILED

    def check_channel_exec_request(self, channel, command: bytes) -> bool:
        """Handle command execution requests"""
        try:
            command_str = command.decode('utf-8').strip()
            logger.info(f"Executing command: {command_str}")

            # Execute command in a separate thread
            threading.Thread(
                target=self.execute_command,
                args=(channel, command_str),
                daemon=True
            ).start()

            return True
        except Exception as e:
            logger.error(f"Error processing command: {e}")
            return False

