            if not self.validate_command(command):
                response = json.dumps({
                    'success': False,
                    'stdout': '',
                    'stderr': 'Command validation failed',
                    'timestamp': datetime.now().isoformat()
                })
                channel.send(response.encode('utf-8'))
                channel.send_exit_status(1)
                return

            # Execute command with timeout
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                timeout=30,
                encoding='utf-8',
                errors='replace'
            )

            # Prepare response
            response = json.dumps({
                'success': result.returncode == 0,
                'stdout': result.stdout,
                'stderr': result.stderr,
                'returncode': result.returncode,
                'timestamp': datetime.now().isoformat()
            })

            # Send response
            channel.send(response.encode('utf-8'))
            channel.send_exit_status(result.returncode)

        except subprocess.TimeoutExpired:
            response = json.dumps({
                'success': False,
                'stdout': '',
                'stderr': 'Command timed out after 30 seconds',
                'timestamp': datetime.now().isoformat()
            })
            channel.send(response.encode('utf-8'))
            channel.send_exit_status(-1)

        except Exception as e:
            response = json.dumps({
                'success': False,
                'stdout': '',
                'stderr': f'Execution error: {str(e)}',
                'timestamp': datetime.now().isoformat()
            })
            channel.send(response.encode('utf-8'))
            channel.send_exit_status(-1)
        finally:
            channel.close()

    def validate_command(self, command: str) -> bool:
        """Validate command for security"""
        # Basic security checks
        dangerous_patterns = [
            'rm -rf /', 'sudo', ';', '&&', '||', '`', '$(',
            '> /dev/', 'cat /etc/shadow', 'chmod 777'
        ]

        # Check for dangerous patterns
        for pattern in dangerous_patterns:
            if pattern in command.lower():
                logger.warning(f"Blocked dangerous command pattern: {pattern}")
                return False

        # Check command length
        if len(command) > 1000:
            logger.warning(f"Command too long: {len(command)} characters")
            return False

        # Allow only specific commands (whitelist approach)
        allowed_commands = [
            'python', 'python3', 'ls', 'cd', 'pwd',
            'echo', 'cat', 'grep', 'find', 'ps'
        ]

        # Check if command starts with allowed command
        first_word = command.split()[0] if command.split() else ''
        if first_word not in allowed_commands:
            logger.warning(f"Command not in whitelist: {first_word}")
            return False

        return True

class SSHServer:
