import com.jcraft.jsch.*;

public class SSHUtils {

    public interface SSHCallback {
        void onSuccess(String result);
        void onError(String error);
    }

    public static void executeSSHCommand(String host, int port, 
                                         String username, String password,
                                         String command, SSHCallback callback) {

        new Thread(() -> {
            Session session = null;
            ChannelExec channel = null;

            try {
                // Create JSch instance
                JSch jsch = new JSch();

                // Create session
                session = jsch.getSession(username, host, port);
                session.setPassword(password);

                // Configure session
                Properties config = new Properties();
                config.put("StrictHostKeyChecking", "no"); // For testing only!
                session.setConfig(config);

                // Connect with timeout
                session.connect(10000); // 10 second timeout

                // Create exec channel
                channel = (ChannelExec) session.openChannel("exec");
                channel.setCommand(command);

                // Get output stream
                InputStream in = channel.getInputStream();
                InputStream err = channel.getErrStream();

                // Connect channel
                channel.connect(5000); // 5 second timeout

                // Read output
                byte[] tmp = new byte[1024];
                StringBuilder output = new StringBuilder();
                StringBuilder error = new StringBuilder();

                while (true) {
                    while (in.available() > 0) {
                        int i = in.read(tmp, 0, 1024);
                        if (i < 0) break;
                        output.append(new String(tmp, 0, i));
                    }

                    while (err.available() > 0) {
                        int i = err.read(tmp, 0, 1024);
                        if (i < 0) break;
                        error.append(new String(tmp, 0, i));
                    }

                    if (channel.isClosed()) {
                        if (in.available() > 0) continue;
                        break;
                    }

                    try {
                        Thread.sleep(100);
                    } catch (Exception e) {
                        // Ignore
                    }
                }

                // Get exit status
                int exitStatus = channel.getExitStatus();

                // Prepare result
                JSONObject result = new JSONObject();
                try {
                    result.put("success", exitStatus == 0);
                    result.put("stdout", output.toString());
                    result.put("stderr", error.toString());
                    result.put("exitcode", exitStatus);
                } catch (JSONException e) {
                    e.printStackTrace();
                }

                final String finalResult = result.toString();

                // Call callback on UI thread
                new Handler(Looper.getMainLooper()).post(() -> {
                    if (callback != null) {
                        callback.onSuccess(finalResult);
                    }
                });

            } catch (Exception e) {
                final String errorMsg = "SSH Error: " + e.getMessage();
                new Handler(Looper.getMainLooper()).post(() -> {
                    if (callback != null) {
                        callback.onError(errorMsg);
                    }
                });
            } finally {
                // Clean up
                if (channel != null) {
                    channel.disconnect();
                }
                if (session != null) {
                    session.disconnect();
                }
            }
        }).start();
    }
}

