        logging.StreamHandler(sys.stdout)
    ]
)
logger = logging.getLogger(__name__)

class AndroidCompatibleServer:
    """
    Server that handles connections from Android devices of all API levels
    """

    def __init__(self, host: str = '0.0.0.0', port: int = 5000):
        """
        Initialize server with backward compatibility support

        Args:
            host: Host IP to bind to
            port: Port to listen on
        """
        self.host = host
        self.port = port
        self.server_socket = None
        self.running = False
        self.clients = {}
        self.android_versions = {}  # Track Android versions for debugging

    def handle_android_client(self, client_socket: socket.socket, address: tuple):
        """
        Handle connection from Android client with version-specific logic

        Args:
            client_socket: Client socket
            address: Client address (ip, port)
        """
        client_id = f"{address[0]}:{address[1]}"
        logger.info(f"Android client connected: {client_id}")

        try:
            # Set timeout for compatibility with older Android versions
            client_socket.settimeout(30.0)

            # Receive data with buffer for older Android versions
            data = b""
            while True:
                chunk = client_socket.recv(1024)
                if not chunk:
                    break
                data += chunk

                # Older Android versions might send smaller chunks
                if len(chunk) < 1024:
                    break

            if not data:
                logger.warning(f"No data received from {client_id}")
                return

            # Parse the command
            try:
                data_str = data.decode('utf-8').strip()

                # Support both JSON and plain text for backward compatibility
                try:
                    command_data = json.loads(data_str)
                    command = command_data.get('command', '')
                    android_version = command_data.get('android_version', 'unknown')

                    # Store Android version for debugging
                    self.android_versions[client_id] = android_version
                    logger.info(f"Android {android_version} client: {client_id}")

                except json.JSONDecodeError:
                    # Fallback for very old Android versions
                    command = data_str
                    android_version = "pre-API-11"
                    self.android_versions[client_id] = android_version

                # Execute command with appropriate timeout
                result = self.execute_command_safely(command, android_version)

                # Send response back
                response = json.dumps(result, ensure_ascii=False)
                client_socket.sendall(response.encode('utf-8'))

                logger.info(f"Command executed for Android {android_version}: {command[:50]}...")

            except UnicodeDecodeError:
                logger.error(f"Encoding error from {client_id}")
                error_response = json.dumps({
                    'success': False,
                    'error': 'Invalid encoding',
                    'compatibility_note': 'Use UTF-8 encoding'
                })
                client_socket.sendall(error_response.encode('utf-8'))

        except socket.timeout:
            logger.warning(f"Timeout for client {client_id}")
        except Exception as e:
            logger.error(f"Error with client {client_id}: {e}")
        finally:
            client_socket.close()
            if client_id in self.clients:
                del self.clients[client_id]
            logger.info(f"Client disconnected: {client_id}")

    def execute_command_safely(self, command: str, android_version: str) -> Dict[str, Any]:
        """
        Execute command with safety checks and Android version awareness

        Args:
            command: Command to execute
            android_version: Android version for compatibility adjustments

        Returns:
            Dictionary with execution results
        """
        start_time = datetime.now()

        # Security validation
        if not self.validate_command(command):
            return {
                'success': False,
                'stdout': '',
                'stderr': 'Command validation failed',
                'android_compatible': True,
                'timestamp': start_time.isoformat()
            }

        try:
            # Adjust timeout based on Android version
            timeout = 45 if android_version == "pre-API-11" else 30

            # Execute command
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                timeout=timeout,
                encoding='utf-8',
                errors='replace'
            )

            end_time = datetime.now()
            execution_time = (end_time - start_time).total_seconds()

            return {
                'success': result.returncode == 0,
                'stdout': result.stdout,
                'stderr': result.stderr,
                'returncode': result.returncode,
                'android_compatible': True,
                'timestamp': start_time.isoformat(),
                'execution_time': execution_time,
                'android_version': android_version
            }

        except subprocess.TimeoutExpired:
            return {
                'success': False,
                'stdout': '',
                'stderr': f'Command timed out after {timeout} seconds',
                'android_compatible': True,
                'timestamp': start_time.isoformat()
            }
        except Exception as e:
            return {
                'success': False,
                'stdout': '',
                'stderr': f'Execution error: {str(e)}',
                'android_compatible': True,
                'timestamp': start_time.isoformat()
            }

    def validate_command(self, command: str) -> bool:
        """
        Validate command for security and compatibility

        Args:
            command: Command to validate

        Returns:
            True if command is safe
        """
        # Basic security checks
        dangerous_patterns = [
            'rm -rf', 'sudo', ';', '&&', '||', '`', '$(',
            '> /dev/', 'cat /etc/', 'chmod 777', 'dd if='
        ]

        for pattern in dangerous_patterns:
            if pattern in command.lower():
                logger.warning(f"Blocked dangerous pattern: {pattern}")
                return False

        # Length check
        if len(command) > 2000:
            logger.warning(f"Command too long: {len(command)} chars")
            return False

        # Allow only specific commands
        allowed_commands = [
            'python', 'python3', 'ls', 'cd', 'pwd',
            'echo', 'cat', 'grep', 'find', 'ps',
            'date', 'whoami', 'uname', 'df', 'free'
        ]

        first_word = command.split()[0] if command.split() else ''
        if first_word not in allowed_commands:
            logger.warning(f"Command not allowed: {first_word}")
            return False

        return True

    def start_server(self):
        """
        Start the backward-compatible server
        """
        try:
            # Create socket with reuse option
            self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.server_socket.bind((self.host, self.port))
            self.server_socket.listen(10)  # Allow multiple connections

            self.running = True
            logger.info(f"Android-Compatible Server started on {self.host}:{self.port}")
            logger.info("Supports Android API levels 1-33+")

            while self.running:
                try:
                    # Accept connections
                    client_socket, address = self.server_socket.accept()

                    # Handle each client in separate thread
                    client_thread = threading.Thread(
                        target=self.handle_android_client,
                        args=(client_socket, address),
                        daemon=True
                    )
                    client_thread.start()

                    # Track client
                    self.clients[f"{address[0]}:{address[1]}"] = {
                        'connected_at': datetime.now().isoformat(),
                        'thread': client_thread
                    }

                except KeyboardInterrupt:
                    logger.info("Server shutdown requested")
                    self.running = False
                    break
                except Exception as e:
                    logger.error(f"Error accepting connection: {e}")

        except Exception as e:
            logger.error(f"Failed to start server: {e}")
        finally:
            self.stop_server()

    def stop_server(self):
        """
        Gracefully stop the server
        """
        logger.info("Stopping server...")
        self.running = False

        # Close all client connections
        for client_id in list(self.clients.keys()):
            logger.info(f"Cleaning up client: {client_id}")

        # Close server socket
        if self.server_socket:
            try:
                self.server_socket.close()
            except:
                pass

        logger.info("Server stopped")

    def get_server_status(self) -> Dict[str, Any]:
        """
        Get server status including Android version statistics

        Returns:
            Dictionary with server status
        """
        android_version_stats = {}
        for version in self.android_versions.values():
            android_version_stats[version] = android_version_stats.get(version, 0) + 1

        return {
            'running': self.running,
            'host': self.host,
            'port': self.port,
            'connected_clients': len(self.clients),
            'android_versions': android_version_stats,
            'total_connections': len(self.android_versions)
        }

