import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import org.json.JSONObject;

public class NetworkExecutorService {

    // Fixed thread pool for network operations
    private static final ExecutorService executorService = 
        Executors.newFixedThreadPool(4);

    // Single thread executor for sequential operations
    private static final ExecutorService singleThreadExecutor = 
        Executors.newSingleThreadExecutor();

    public interface NetworkCallback {
        void onSuccess(String response);
        void onError(String error);
    }

    /**
     * Modern approach using ExecutorService for network operations
     * Compatible with API 11+ and avoids AsyncTask deprecation
     */
    public static void executeCommand(String ip, int port, String command, 
                                      NetworkCallback callback) {

        // Submit task to thread pool
        executorService.submit(() -> {
            performNetworkOperation(ip, port, command, callback);
        });
    }

    /**
     * Execute with timeout control
     */
    public static void executeCommandWithTimeout(String ip, int port, String command,
                                                 long timeoutSeconds, NetworkCallback callback) {

        Callable<String> networkTask = () -> {
            return performNetworkOperationSync(ip, port, command);
        };

        Future<String> future = executorService.submit(networkTask);

        executorService.submit(() -> {
            try {
                String result = future.get(timeoutSeconds, TimeUnit.SECONDS);
                notifySuccess(result, callback);
            } catch (Exception e) {
                notifyError("Timeout or execution error: " + e.getMessage(), callback);
                future.cancel(true); // Cancel the task if it's still running
            }
        });
    }

    /**
     * Execute multiple commands sequentially
     */
    public static void executeCommandsSequentially(String ip, int port, 
                                                   String[] commands, 
                                                   NetworkCallback callback) {

        singleThreadExecutor.submit(() -> {
            for (String command : commands) {
                try {
                    String result = performNetworkOperationSync(ip, port, command);
                    // Process each result as needed
                    JSONObject jsonResult = new JSONObject(result);
                    boolean success = jsonResult.getBoolean("success");

                    if (!success) {
                        notifyError("Command failed: " + jsonResult.getString("stderr"), callback);
                        return;
                    }
                } catch (Exception e) {
                    notifyError("Error executing command: " + e.getMessage(), callback);
                    return;
                }
            }
            notifySuccess("All commands executed successfully", callback);
        });
    }

    private static void performNetworkOperation(String ip, int port, 
                                                String command, NetworkCallback callback) {
        try {
            String result = performNetworkOperationSync(ip, port, command);
            notifySuccess(result, callback);
        } catch (Exception e) {
            notifyError("Network error: " + e.getMessage(), callback);
        }
    }

    private static String performNetworkOperationSync(String ip, int port, String command) 
            throws IOException {

        Socket socket = null;
        try {
            // Create socket with timeout
            socket = new Socket();
            socket.connect(new InetSocketAddress(ip, port), 10000); // 10 second timeout
            socket.setSoTimeout(15000); // 15 second read timeout

            // Send command
            OutputStream output = socket.getOutputStream();
            output.write(command.getBytes("UTF-8"));
            output.flush();

            // Read response
            InputStream input = socket.getInputStream();
            byte[] buffer = new byte[4096];
            StringBuilder response = new StringBuilder();
            int bytesRead;

            while ((bytesRead = input.read(buffer)) != -1) {
                response.append(new String(buffer, 0, bytesRead, "UTF-8"));
            }

            return response.toString();

        } finally {
            if (socket != null) {
                try {
                    socket.close();
                } catch (IOException e) {
                    // Ignore close errors
                }
            }
        }
    }

    private static void notifySuccess(String result, NetworkCallback callback) {
        if (callback != null) {
            new Handler(Looper.getMainLooper()).post(() -> {
                callback.onSuccess(result);
            });
        }
    }

    private static void notifyError(String error, NetworkCallback callback) {
        if (callback != null) {
            new Handler(Looper.getMainLooper()).post(() -> {
                callback.onError(error);
            });
        }
    }

    /**
     * Clean shutdown of executors
     */
    public static void shutdown() {
        executorService.shutdown();
        singleThreadExecutor.shutdown();

        try {
            if (!executorService.awaitTermination(5, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
            if (!singleThreadExecutor.awaitTermination(5, TimeUnit.SECONDS)) {
                singleThreadExecutor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            singleThreadExecutor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }
