      const job = {
        id,
        status: 'queued', // queued | running | completed | failed | cancelled
        startedAt: null,
        finishedAt: null,
        processed: 0,
        succeeded: 0,
        failed: 0,
        batches: 0,
        errors: [],
        meta: {},
        ...initial
      };
      _jobs.set(id, job);
      return job;
    },
    get(id) {
      return _jobs.get(id);
    },
    update(id, patch) {
      const job = _jobs.get(id);
      if (!job) return;
      Object.assign(job, patch);
      return job;
    },
    all() {
      return Array.from(_jobs.values());
    }
  };
})();

