# Repository for bulk inserting/upserting customers in PostgreSQL.
# Assumes a "customers" table with a unique constraint on "email".
# Adjust to match your schema.

const pool = require('../db/pool');

async function upsertCustomersBatch(rows) {
  if (!rows || rows.length === 0) return;

  // Build parameterized bulk upsert
  const cols = [
    'email', 'first_name', 'last_name', 'phone',
    'address', 'city', 'state', 'zip'
  ];

  const values = [];
  const placeholders = [];

  rows.forEach((r, i) => {
    const baseIndex = i * cols.length;
    placeholders.push(
      `(${cols.map((_, j) => `$${baseIndex + j + 1}`).join(', ')})`
    );
    values.push(
      r.email ?? null,
      r.first_name ?? null,
      r.last_name ?? null,
      r.phone ?? null,
      r.address ?? null,
      r.city ?? null,
      r.state ?? null,
      r.zip ?? null
    );
  });

  const conflictTarget = 'email'; // adjust if different
  const updateAssignments = cols
    .filter((c) => c !== conflictTarget)
    .map((c) => `${c} = EXCLUDED.${c}`)
    .join(', ');

  const sql = `
    INSERT INTO customers (${cols.join(', ')})
    VALUES ${placeholders.join(', ')}
    ON CONFLICT (${conflictTarget})
    DO UPDATE SET ${updateAssignments};
  `;

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query(sql, values);
    await client.query('COMMIT');
  } catch (e) {
    await client.query('ROLLBACK');
    throw e;
  } finally {
    client.release();
  }
}

module.exports = { upsertCustomersBatch };


