// TerrainGenerationJob.cs - Using Unity's Jobs System
using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;
using UnityEngine;

public struct TerrainGenerationJob : IJobParallelFor
{
    public NativeArray<Vector3> vertices;
    public NativeArray<Vector2> uv;
    public NativeArray<int> triangles;

    public int resolution;
    public float chunkSize;
    public float3 chunkPosition;
    public float noiseScale;
    public float heightScale;

    public void Execute(int index)
    {
        int x = index % (resolution + 1);
        int z = index / (resolution + 1);

        float xPos = (float)x / resolution * chunkSize;
        float zPos = (float)z / resolution * chunkSize;

        // Sample height using noise function
        float yPos = noise.cnoise(new float2(
            (xPos + chunkPosition.x) * noiseScale,
            (zPos + chunkPosition.z) * noiseScale
        )) * heightScale;

        vertices[index] = new Vector3(xPos, yPos, zPos);
        uv[index] = new Vector2((float)x / resolution, (float)z / resolution);

        // Generate triangles (every other vertex)
        if (x < resolution && z < resolution)
        {
            int triIndex = (z * resolution + x) * 6;
            int i = (z * (resolution + 1)) + x;

            triangles[triIndex] = i;
            triangles[triIndex + 1] = i + resolution + 1;
            triangles[triIndex + 2] = i + 1;

            triangles[triIndex + 3] = i + 1;
            triangles[triIndex + 4] = i + resolution + 1;
            triangles[triIndex + 5] = i + resolution + 2;
        }
    }
}

// Usage:
public JobHandle GenerateMeshJob(ChunkData chunkData)
{
    int vertexCount = (chunkData.resolution + 1) * (chunkData.resolution + 1);
    int triangleCount = chunkData.resolution * chunkData.resolution * 6;

    NativeArray<Vector3> vertices = new NativeArray<Vector3>(vertexCount, Allocator.TempJob);
    NativeArray<Vector2> uv = new NativeArray<Vector2>(vertexCount, Allocator.TempJob);
    NativeArray<int> triangles = new NativeArray<int>(triangleCount, Allocator.TempJob);

    var job = new TerrainGenerationJob
    {
        vertices = vertices,
        uv = uv,
        triangles = triangles,
        resolution = chunkData.resolution,
        chunkSize = chunkData.size,
        chunkPosition = chunkData.position,
        noiseScale = 0.1f,
        heightScale = 50f
    };

    return job.Schedule(vertexCount, 64);
}
