// DynamicLODManager.cs - Adjust LOD based on performance metrics
using System.Collections;
using UnityEngine;

public class DynamicLODManager : MonoBehaviour
{
    public TerrainChunkController terrainController;

    [Header("Performance Targets")]
    public float targetFrameTime = 16.67f; // 60 FPS
    public int targetDrawCalls = 100;
    public float memoryWarningThreshold = 500f; // MB

    [Header("LOD Adjustment")]
    public float lodAdjustmentSpeed = 0.1f;
    public int minLODLevel = 0;
    public int maxLODLevel = 3;

    private float currentFrameTime;
    private int currentDrawCalls;
    private float currentMemoryUsage;

    private Coroutine monitoringCoroutine;

    void Start()
    {
        monitoringCoroutine = StartCoroutine(MonitorPerformance());
    }

    IEnumerator MonitorPerformance()
    {
        while (true)
        {
            // Sample performance metrics
            currentFrameTime = Time.deltaTime * 1000f; // Convert to ms
            currentDrawCalls = UnityEngine.Rendering.RenderPipelineManager.currentPipeline
                ? UnityEngine.Rendering.RenderPipelineManager.currentPipeline.GetType()
                    .GetProperty("drawCalls")?.GetValue(null) as int? ?? 0
                : 0;

            // Adjust LOD based on performance
            AdjustLODBasedOnPerformance();

            yield return new WaitForSeconds(1f); // Check every second
        }
    }

    void AdjustLODBasedOnPerformance()
    {
        // Calculate performance score (0-1, where 1 is optimal)
        float frameTimeScore = Mathf.Clamp01(targetFrameTime / currentFrameTime);
        float drawCallScore = Mathf.Clamp01((float)targetDrawCalls / currentDrawCalls);

        float performanceScore = (frameTimeScore + drawCallScore) / 2f;

        // Adjust render distance based on performance
        int optimalRenderDistance = Mathf.RoundToInt(
            terrainController.renderDistance * performanceScore
        );

        optimalRenderDistance = Mathf.Clamp(
            optimalRenderDistance, 
            minLODLevel, 
            maxLODLevel
        );

        // Smoothly adjust render distance
        terrainController.renderDistance = Mathf.Lerp(
            terrainController.renderDistance,
            optimalRenderDistance,
            lodAdjustmentSpeed
        );

        // Log adjustments for debugging
        if (Mathf.Abs(terrainController.renderDistance - optimalRenderDistance) > 0.1f)
        {
            Debug.Log($"Adjusting LOD: Render Distance = {terrainController.renderDistance}, " +
