                {
                    width = heightmapResolution,
                    height = heightmapResolution,
                    noiseType = VistaNoiseType.Simplex,  // Faster than Perlin
                    octaves = 4,  // Reduced from default 6
                    persistence = 0.4f,
                    lacunarity = 1.8f,
