                return heightmap;
            }

            void RemoveOldestCacheEntries()
            {
                // Remove oldest 20% of cache entries
                int entriesToRemove = heightmapCache.Count / 5;
                var keysToRemove = new List<Vector2Int>();

                foreach (var entry in heightmapCache)
                {
                    if (keysToRemove.Count >= entriesToRemove) break;
                    keysToRemove.Add(entry.Key);
                }

                foreach (var key in keysToRemove)
                {
                    heightmapCache.Remove(key);
                }
            }
