// Dart code using the `image` package for image processing
import 'dart:typed_data';
import 'package:image/image.dart';

/// Slices an image into four equal quadrants from the center.
/// 
/// Accepts either a file path or raw image bytes as input.
/// Returns a list of byte arrays for the four quadrants:
/// [top-left, top-right, bottom-left, bottom-right].
Future<List<Uint8List>> sliceImage({String? imagePath, Uint8List? imageBytes}) async {
  // Validate input
  if (imagePath == null && imageBytes == null) {
    throw ArgumentError('Either imagePath or imageBytes must be provided');
  }

  // Load image bytes
  Uint8List bytes = imagePath != null 
    ? await File(imagePath).readAsBytes() 
    : imageBytes!;

  // Decode image
  Image? image = decodeImage(bytes);
  if (image == null) throw FormatException('Failed to decode image');

  // Calculate center
  int halfWidth = image.width ~/ 2;
  int halfHeight = image.height ~/ 2;

  // Crop quadrants
  Image topLeft = copyCrop(image, 0, 0, halfWidth, halfHeight);
  Image topRight = copyCrop(image, halfWidth, 0, halfWidth, halfHeight);
  Image bottomLeft = copyCrop(image, 0, halfHeight, halfWidth, halfHeight);
  Image bottomRight = copyCrop(image, halfWidth, halfHeight, halfWidth, halfHeight);

  // Encode quadrants to PNG bytes
  return [
    Uint8List.fromList(encodePng(topLeft)),
    Uint8List.fromList(encodePng(topRight)),
    Uint8List.fromList(encodePng(bottomLeft)),
    Uint8List.fromList(encodePng(bottomRight)),
  ];
}
