using System;
using System.Collections.Generic;
using System.Linq;

// Advance Steel API Namespaces
using Autodesk.AdvanceSteel.CADAccess;
using Autodesk.AdvanceSteel.Geometry;
using Autodesk.AdvanceSteel.Modelling;
using Autodesk.AdvanceSteel.ConstructionTypes;
using Autodesk.AdvanceSteel.Annotations;
using Autodesk.AdvanceSteel.DocumentManagement;

namespace AdvanceSteelCartesianDim
{
    public class PlateDimensioner
    {
        public void CreateCartesianDimensionsForPlate(ObjectId plateId)
        {
            // 1. Start a Transaction
            // Transactions are required for any read/write operation in Advance Steel
            using (var trans = TransactionManager.StartTransaction())
            {
                try
                {
                    // 2. Open the Plate object
                    // We open for read first to get geometry data
                    Plate plate = DatabaseManager.Open(plateId) as Plate;
                    if (plate == null) return;

                    // 3. Determine the Origin (Bottom-Left)
                    // We get the outer contour of the plate to find the minimum extents
                    Polyline3d contour = plate.GetOuterContour();
                    Point3d[] vertices = contour.Vertices;

                    double minX = vertices.Min(v => v.x);
                    double minY = vertices.Min(v => v.y);
                    Point3d originPoint = new Point3d(minX, minY, 0);

                    // 4. Collect Hole Centers
                    // We iterate through the plate's features to find holes
                    List<Point3d> holePoints = new List<Point3d>();
                    foreach (var featureId in plate.GetFeatures())
                    {
                        Feature feature = DatabaseManager.Open(featureId) as Feature;
                        if (feature is HoleFeature hole)
                        {
                            // Get the center point of the hole
                            holePoints.Add(hole.CenterPoint);
                        }
                    }

                    // 5. Create the Linear Dimension Object
                    // Define where the dimension line will sit (e.g., 100 units below the plate)
                    Point3d dimLineLocation = new Point3d(minX, minY - 100, 0);
                    Vector3d dimDirection = Vector3d.kXAxis; // Dimensioning along the X-axis

                    // Initialize the LinearDimension
                    LinearDimension cartesianDim = new LinearDimension(dimLineLocation, dimDirection, null);

                    // SET THE TYPE TO ABSOLUTE (Cartesian)
                    // This is the key property that forces 0, 100, 250... instead of 100, 150...
                    cartesianDim.DimensionType = LinearDimension.eDimensionType.kAbsolute;

                    // 6. Add Points to the Dimension Chain
                    // First, add the origin (0,0 point)
                    cartesianDim.AddDimensionPoint(new DimensionPoint(originPoint));

                    // Then, add all collected hole points
                    foreach (Point3d hp in holePoints)
                    {
                        cartesianDim.AddDimensionPoint(new DimensionPoint(hp));
                    }

                    // 7. Write to Database
                    // This commits the new dimension object to the drawing
                    cartesianDim.WriteToDb();

                    // Commit the transaction
                    trans.Commit();
                }
                catch (Exception ex)
                {
                    // Rollback if something goes wrong
                    trans.Rollback();
                    Console.WriteLine("Error: " + ex.Message);
                }
            }
        }
    }
}
```

### Detailed Explanation of the Implementation

1.  **Transaction Management:** In the .NET API, every action that modifies the database must be wrapped in a `Transaction`. This ensures data integrity.
2.  **Geometry Extraction (`GetOuterContour`):** To find the "Bottom Left," we query the plate's boundary. By using LINQ (`.Min()`), we find the lowest X and Y values. This serves as our `0,0` reference point.
3.  **Feature Iteration:** Holes in Advance Steel are not properties of the plate; they are `Features` attached to it. We loop through `GetFeatures()` and filter for `HoleFeature`.
4.  **`eDimensionType.kAbsolute`:** This is the specific Enum value that solves your problem. While the Drawing Style Manager tries to be "smart" and might split chains, setting this via the API forces the engine to treat all points as part of a single coordinate string relative to the first point added.
5.  **Dimension Points:** The `DimensionPoint` class is a wrapper for the `Point3d`. The first point you add to the `LinearDimension` object becomes the zero-reference for the Cartesian string.

