const papa = require('papa');

const processCSVStream = (fileContent) => {
  const stream = papa.parse(papa.NODE_STREAM_INPUT, {
    header: true,
    dynamicTyping: true,
    step: (results, parser) => {
      parser.pause();
      const batch = results.data.map((row) => ({
        name: row.name,
        email: row.email,
        // Map other fields as needed
      }));
      parser.resume();
      stream.emit('data', batch);
    },
    complete: () => {
      stream.emit('end');
    },
    error: (err) => {
      stream.emit('error', err);
    },
  });

  stream.write(fileContent);
  stream.end();

  return stream;
};

module.exports = { processCSVStream };
```

