"use client";

import React, { useState, useRef } from 'react';
import { db } from "@/lib/firebase";
import { doc, updateDoc, addDoc, collection, serverTimestamp } from "firebase/firestore";
import { MarkdownEditor, MarkdownRenderer } from 'markdownrx';

/**
 * DocumentationEditor Component
 * Provides a styled interface for editing, previewing, and uploading markdown.
 */
export default function DocumentationEditor({ initialDoc, onSaveSuccess }) {
  const [content, setContent] = useState(initialDoc?.content || "");
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef(null);

  // Handle saving content to Firebase
  const handleSave = async () => {
    if (!content) return;
    setIsSaving(true);
    try {
      if (initialDoc?.id) {
        // Update existing document
        const docRef = doc(db, "docs", initialDoc.id);
        await updateDoc(docRef, {
          content: content,
          lastUpdated: serverTimestamp()
        });
      } else {
        // Create new document if none exists
        await addDoc(collection(db, "docs"), {
          title: "New Document",
          content: content,
          createdAt: serverTimestamp()
        });
      }
      setIsEditing(false);
      if (onSaveSuccess) onSaveSuccess();
    } catch (error) {
      console.error("Save Error:", error);
      alert("Failed to save changes.");
    } finally {
      setIsSaving(false);
    }
  };

  // Handle Markdown File Upload
  const handleFileUpload = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target.result;
      setContent(text); // Update editor state with file content
      setIsEditing(true); // Switch to edit mode automatically
    };
    reader.readAsText(file);
  };

  return (
    <div className="w-full max-w-5xl mx-auto bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
      {/* Editor Toolbar */}
      <div className="flex items-center justify-between px-6 py-4 bg-slate-50 border-b border-slate-200">
        <div className="flex space-x-2">
          <button
            onClick={() => setIsEditing(false)}
            className={`px-4 py-2 text-sm font-medium rounded-md transition ${
              !isEditing ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-600 hover:text-slate-900'
            }`}
          >
            Preview
          </button>
          <button
            onClick={() => setIsEditing(true)}
            className={`px-4 py-2 text-sm font-medium rounded-md transition ${
              isEditing ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-600 hover:text-slate-900'
            }`}
          >
            Edit Source
          </button>
        </div>

        <div className="flex items-center space-x-3">
          {/* Hidden File Input */}
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileUpload} 
            accept=".md" 
            className="hidden" 
          />

          <button
            onClick={() => fileInputRef.current.click()}
            className="text-slate-600 hover:text-indigo-600 text-sm font-medium px-3 py-2"
          >
            Upload .md
          </button>

          <button
            onClick={handleSave}
            disabled={isSaving}
            className="bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2 rounded-lg text-sm font-semibold transition disabled:opacity-50"
          >
            {isSaving ? "Saving..." : "Save Changes"}
          </button>
        </div>
      </div>

      {/* Content Area */}
      <div className="p-8 min-h-[600px]">
        {isEditing ? (
          <div className="h-full border-none focus:ring-0">
            <MarkdownEditor
              value={content}
              onChange={(val) => setContent(val)}
              placeholder="Write your documentation using Markdown..."
              className="w-full h-full min-h-[500px] font-mono text-sm focus:outline-none"
            />
          </div>
        ) : (
          <article className="prose prose-slate prose-indigo max-w-none">
            {/* 
                The 'prose' class from @tailwindcss/typography 
                handles all documentation formatting (h1, p, code, etc.)
            */}
            {content ? (
              <MarkdownRenderer content={content} />
            ) : (
              <p className="text-slate-400 italic text-center py-20">
                No content to display. Click "Edit" to start writing.
              </p>
            )}
          </article>
        )}
      </div>
    </div>
  );
}
```

