To build a robust multi-page documentation system in Next.js, we must combine a dynamic sidebar for navigation with a centralized state that manages the "active" document. 

Below is the detailed explanation and implementation.

### 1. The Importance of the `"use client"` Directive

In the Next.js App Router architecture, components are **Server Components** by default. Server Components are rendered on the server to improve performance and SEO, but they have limitations:
*   **No State or Effects**: You cannot use `useState` or `useEffect` because the server doesn't maintain a persistent state for the user's browser session.
*   **No Browser APIs**: You cannot access the `window` object, `localStorage`, or handle browser events like `onClick`.
*   **No Real-time Listeners**: Firebase's `onSnapshot` requires a persistent connection from the client's browser to the database.

By adding `"use client"` at the very top of the file, you instruct Next.js to treat this component (and its imports) as a **Client Component**. This is mandatory for our documentation system because we need to track which page is currently selected, handle text input in the editor, and listen for real-time updates from Firestore.

### 2. Implementing the Multi-Page System

The multi-page functionality is achieved by:
1.  **Firestore Collection**: Storing each documentation page as a separate document in a `docs` collection.
2.  **Sidebar Navigation**: Fetching the list of document titles and IDs to create a navigation menu.
3.  **Active State**: Using a state variable (`activeDoc`) to determine which content to render in the main viewer/editor.

### Implementation

```python
# Note: This is JavaScript/TypeScript code for a Next.js application, 
# formatted in a Python block as requested.

"use client";

import React, { useState, useEffect } from 'react';
import { db } from "@/lib/firebase";
import { 
  collection, 
  addDoc, 
  doc, 
  updateDoc, 
  onSnapshot, 
  query, 
  orderBy,
  serverTimestamp 
} from "firebase/firestore";

// MarkdownRX components for professional editing and rendering
import { MarkdownEditor, MarkdownRenderer } from 'markdownrx'; 

/**
 * DocumentationSystem
 * A multi-page management interface for documentation.
 */
export default function DocumentationSystem() {
  // --- State Management (Requires "use client") ---
  const [documents, setDocuments] = useState([]);
  const [activeDoc, setActiveDoc] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState("");
  const [loading, setLoading] = useState(true);

  // 1. Fetch all documentation pages from Firebase
  useEffect(() => {
    // It is vital to ensure @/lib/firebase is correctly configured
    const q = query(collection(db, "docs"), orderBy("createdAt", "asc"));

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const docsData = snapshot.docs.map(d => ({
        id: d.id,
        ...d.data()
      }));
      setDocuments(docsData);

      // Auto-select the first document if none is active
      if (docsData.length > 0 && !activeDoc) {
        setActiveDoc(docsData[0]);
        setEditContent(docsData[0].content);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, [activeDoc]);

  // 2. Create a new documentation page
  const handleCreateNew = async () => {
    const title = prompt("Enter document title:");
    if (!title) return;

    const newDoc = {
      title,
      content: `# ${title}\n\nNew documentation content starts here...`,
      createdAt: serverTimestamp(),
    };

    const docRef = await addDoc(collection(db, "docs"), newDoc);
    // Switch to the new document immediately
    setActiveDoc({ id: docRef.id, ...newDoc });
    setEditContent(newDoc.content);
    setIsEditing(true);
  };

  // 3. Save changes to Firestore
  const handleSave = async () => {
    if (!activeDoc) return;
    try {
      const docRef = doc(db, "docs", activeDoc.id);
      await updateDoc(docRef, {
        content: editContent,
        lastUpdated: serverTimestamp(),
      });
      setIsEditing(false);
    } catch (error) {
      console.error("Error updating document:", error);
      alert("Failed to save changes.");
    }
  };

  if (loading) return <div className="p-10 text-center">Loading System...</div>;

  return (
    <div className="flex h-screen bg-slate-50 text-slate-900">
      {/* SIDEBAR: Multi-page Navigation */}
      <aside className="w-64 bg-white border-r border-slate-200 flex flex-col">
        <div className="p-4 border-b border-slate-200 flex justify-between items-center">
          <h2 className="font-bold text-lg">Docs</h2>
          <button 
            onClick={handleCreateNew}
            className="p-1 bg-indigo-600 text-white rounded hover:bg-indigo-700 transition"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M10 3a1 1 0 011 1v5h5a1 1 0 110 2h-5v5a1 1 0 11-2 0v-5H4a1 1 0 110-2h5V4a1 1 0 011-1z" clipRule="evenodd" />
            </svg>
          </button>
        </div>
        <nav className="flex-1 overflow-y-auto p-2 space-y-1">
          {documents.map((doc) => (
            <button
              key={doc.id}
              onClick={() => { 
                setActiveDoc(doc); 
                setEditContent(doc.content);
                setIsEditing(false); 
              }}
              className={`w-full text-left px-3 py-2 rounded-md text-sm transition ${
                activeDoc?.id === doc.id 
                ? 'bg-indigo-50 text-indigo-700 font-semibold' 
                : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              {doc.title}
            </button>
          ))}
        </nav>
      </aside>

      {/* MAIN CONTENT: Editor and Renderer */}
      <main className="flex-1 flex flex-col overflow-hidden bg-white">
        {activeDoc ? (
          <>
            <header className="h-16 border-b border-slate-200 px-8 flex justify-between items-center">
              <h1 className="text-xl font-semibold">{activeDoc.title}</h1>
              <div className="flex gap-2">
                {isEditing ? (
                  <>
                    <button onClick={() => setIsEditing(false)} className="px-4 py-2 text-sm text-slate-600">Cancel</button>
                    <button onClick={handleSave} className="px-4 py-2 text-sm bg-indigo-600 text-white rounded-md shadow-sm">Save</button>
                  </>
                ) : (
                  <button onClick={() => setIsEditing(true)} className="px-4 py-2 text-sm border border-slate-300 rounded-md hover:bg-slate-50">Edit Page</button>
                )}
              </div>
            </header>

            <div className="flex-1 overflow-y-auto p-8">
              <div className="max-w-4xl mx-auto">
                {isEditing ? (
                  <div className="border rounded-lg overflow-hidden shadow-sm">
                    <MarkdownEditor
                      value={editContent}
                      onChange={(val) => setEditContent(val)}
                      minHeight="600px"
                    />
