    public static int lat(int[][] input, int[][] output, int[] sbox, int a, int b) {
        int count = 0;
        for (int x = 0; x < 8; x++) {
            int index = input[x][0] * 4 + input[x][1] * 2 + input[x][2];
            int fx = sbox[index];

