"""
using UnityEngine;
using UnityEngine.UI;

public class TrajectoryPrediction : MonoBehaviour
{
    public LineRenderer trajectoryLine;
    public Transform ball;
    public float dragMultiplier = 0.1f;
    public int trajectorySteps = 10;
    public float stepDistance = 1.0f;

    private Vector2 dragStart;
    private Vector2 velocity;
    private bool isDragging = false;
    private Camera mainCamera;

    void Start()
    {
        mainCamera = Camera.main;
        trajectoryLine.enabled = false;
    }

    void Update()
    {
        if (Input.GetMouseButtonDown(0))
        {
            dragStart = GetMousePosition();
            isDragging = true;
            trajectoryLine.enabled = true;
        }

        if (isDragging)
        {
            Vector2 currentMouse = GetMousePosition();
            velocity = (currentMouse - dragStart) * dragMultiplier;
            DrawTrajectory(currentMouse, velocity);
        }

        if (Input.GetMouseButtonUp(0))
        {
            isDragging = false;
            trajectoryLine.enabled = false;
            LaunchBall(velocity);
        }
    }

    Vector2 GetMousePosition()
    {
        return mainCamera.ScreenToWorldPoint(Input.mousePosition);
    }

    void DrawTrajectory(Vector2 startPos, Vector2 velocity)
    {
        trajectoryLine.positionCount = trajectorySteps;
        for (int i = 0; i < trajectorySteps; i++)
        {
            float t = i * stepDistance;
            Vector2 pos = startPos + velocity * t;
            trajectoryLine.SetPosition(i, pos);
        }
    }

    void LaunchBall(Vector2 launchVelocity)
    {
        Rigidbody2D rb = ball.GetComponent<Rigidbody2D>();
        rb.velocity = launchVelocity;
    }
}
