% MATLAB ABS Simulation Code
% File: abs_simulation.m

% Main script
function abs_simulation
    % Vehicle Parameters
    m = 1200;      % Vehicle mass (kg)
    I = 1.5;       % Wheel moment of inertia (kg.m^2)
    R = 0.3;       % Tire radius (m)
    Fz = m * 9.81; % Vertical load (N)

    % Simulation Parameters
    tspan = [0 5]; % Time span
    dt = 0.01;     % Time step
    t = tspan(1):dt:tspan(2);

    % Initial Conditions [vehicle speed, wheel speed, angular velocity]
    y0 = [20; 20; 20/R];  % 20 m/s initial speed

    % Solve ODE
    [t, sol] = ode45(@(t,y) wheel_dynamics(t, y, m, R, I, Fz), tspan, y0);

    % Extract results
    v_vehicle = sol(:,1);
    v_wheel = sol(:,2);
    omega = sol(:,3);
    slip = arrayfun(@(i) calculate_slip(v_vehicle(i), v_wheel(i)), 1:length(t));
    mu = arrayfun(@(s) tire_model(s), slip);
    torque = arrayfun(@(ti) braking_torque(ti), t);

    % Plot Results
    figure;
    subplot(2,2,1);
    plot(t, v_vehicle, 'b', t, v_wheel, 'r');
    title('Speeds (m/s)');
    xlabel('Time (s)');
    legend('Vehicle', 'Wheel');

    subplot(2,2,2);
    plot(t, slip, 'g');
    title('Slip Ratio');
    xlabel('Time (s)');

    subplot(2,2,3);
    plot(t, mu, 'm');
    title('Friction Coefficient');
    xlabel('Time (s)');

    subplot(2,2,4);
    plot(t, torque, 'k');
    title('Braking Torque (Nm)');
    xlabel('Time (s)');
    sgtitle('ABS Simulation Results');
end

% Braking Torque Function
function torque = braking_torque(t, t_start, torque_max)
    if nargin <2, t_start = 2; end
    if nargin <3, torque_max = 2000; end
    torque = torque_max * (t >= t_start);
end

% Ramp Signal Function
function signal = ramp_signal(t, slope)
    if nargin <2, slope = 100; end
    signal = slope * t;
end

% Tire Model (Simplified Magic Formula)
function mu = tire_model(slip, mu_max, s_max)
    if nargin <2, mu_max = 0.9; end
    if nargin <3, s_max = 0.2; end
    if slip > 0
        mu = mu_max * (1 - exp(-s_max/slip));
    else
        mu = 0;
    end
end

% Slip Calculation
function slip = calculate_slip(v_vehicle, v_wheel)
    if v_vehicle <= 0
        slip = 0;
    else
        slip = (v_vehicle - v_wheel) / v_vehicle;
    end
end

% ABS Control Logic
function mod = abs_cycle(slip, threshold)
    if nargin <2, threshold = 0.15; end
    mod = 0.5 * (slip > threshold) + 1.0 * (slip <= threshold);
end

% Wheel Dynamics Model
function dydt = wheel_dynamics(t, y, m, R, I, Fz)
    v_vehicle = y(1);
    v_wheel = y(2);
    omega = y(3);

    % Calculate slip
    slip = calculate_slip(v_vehicle, v_wheel);

    % Tire force
    mu = tire_model(slip);
    Fx = mu * Fz;

    % Braking torque with ABS modulation
    T_brake = braking_torque(t) * abs_cycle(slip);

    % Equations of motion
    dv_vehicle = -Fx / m;
    domega = (Fx * R - T_brake) / I;

    dydt = [dv_vehicle; dv_vehicle; domega];
end
