% MATLAB ABS Simulation with User Input and Enhanced Visualization
% File: abs_simulation.m

function abs_simulation
    % Main script for ABS simulation with user input and animation

    % Set up figure for animation
    fig = figure('Name', 'ABS Simulation Results', 'NumberTitle', 'off', ...
                 'WindowState', 'maximized');

    % Get user parameters
    params = getUserParameters();

    % Run simulation
    [t, sol] = runSimulation(params);

    % Extract results
    v_vehicle = sol(:,1);
    v_wheel = sol(:,2);
    omega = sol(:,3);

    % Precompute derived results
    slip = zeros(size(t));
    mu = zeros(size(t));
    torque = zeros(size(t));

    for i = 1:length(t)
        slip(i) = calculateSlip(v_vehicle(i), v_wheel(i));
        mu(i) = tireModel(slip(i));
        torque(i) = brakingTorque(t(i), params.t_start, params.slope, ...
            params.torque_max) * absCycle(slip(i), params.threshold);
    end

    % Animate results
    animateResults(t, v_vehicle, v_wheel, slip, mu, torque, params);

    % Display parameter values used
    displayParameters(params);
end

% === Local Functions ===

function params = getUserParameters()
    % Interactive parameter input with default values

    % Default values
    defaults = {'1200', '1.5', '0.3', '2', '1000', '2000', '0.15'};

    % Input dialog setup
    prompt = {'Vehicle mass (kg):', 'Wheel inertia (kg·m²):', ...
              'Tire radius (m):', 'Brake start time (s):', ...
              'Torque ramp slope (Nm/s):', 'Max torque (Nm):', ...
              'ABS threshold (0-1):'};

    dlgTitle = 'ABS Simulation - Parameter Input';
    dims = [1 35];

    % Display input dialog
    paramsCell = inputdlg(prompt, dlgTitle, dims, defaults);

    % Convert to numeric values
    params.m = str2double(paramsCell{1});  % Vehicle mass
    params.I = str2double(paramsCell{2});  % Wheel inertia
    params.R = str2double(paramsCell{3});  % Tire radius
    params.t_start = str2double(paramsCell{4});  % Brake start time
    params.slope = str2double(paramsCell{5});    % Torque slope
    params.torque_max = str2double(paramsCell{6});  % Max torque
    params.threshold = str2double(paramsCell{7});  % ABS threshold

    % Derived parameter
    params.Fz = params.m * 9.81;  % Vertical load
end

function [t, sol] = runSimulation(params)
    % Run ODE solver for ABS simulation

    % Simulation time span
    tspan = [0 5];  % 5 seconds total
    dt = 0.01;      % Time step

    % Initial conditions: [vehicle speed, wheel speed, angular velocity]
    y0 = [20; 20; 20/params.R];  % 20 m/s initial speed

    % Solve ODE
    [t, sol] = ode45(@(t,y) wheelDynamics(t, y, params), tspan, y0);
end

function dydt = wheelDynamics(t, y, params)
    % System of differential equations for wheel dynamics

    % State variables
    v_vehicle = y(1);  % Vehicle speed
    v_wheel = y(2);    % Wheel speed
    omega = y(3);      % Angular velocity

    % Calculate slip
    slip = calculateSlip(v_vehicle, v_wheel);

    % Tire force calculation
    mu = tireModel(slip);              % Friction coefficient
    Fx = mu * params.Fz;               % Longitudinal force

    % Braking torque with ABS modulation
    T_brake = brakingTorque(t, params.t_start, params.slope, params.torque_max) * ...
              absCycle(slip, params.threshold);

    % Equations of motion
    dv_vehicle = -Fx / params.m;       % Vehicle deceleration
    domega = (Fx * params.R - T_brake) / params.I;  % Wheel angular acceleration

    % Derivatives
    dydt = [dv_vehicle; dv_vehicle; domega];
end

function torque = brakingTorque(t, t_start, slope, torque_max)
    % Braking torque with ramp profile and saturation

    % Default values if inputs missing
    if nargin < 2, t_start = 2; end
    if nargin < 3, slope = 100; end
    if nargin < 4, torque_max = 2000; end

    % Torque calculation
    if t < t_start
        torque = 0;  % No torque before brake start
    else
        % Ramp profile with saturation
        torque = slope * (t - t_start);
        torque = min(torque, torque_max);  % Limit to max torque
    end
end

function mu = tireModel(slip, mu_max, s_max)
    % Simplified Magic Formula tire model

    % Default values if inputs missing
    if nargin < 2, mu_max = 0.9; end
    if nargin < 3, s_max = 0.2; end

    % Friction coefficient calculation
    if slip <= 0
        mu = 0;  % No slip means no friction
    else
        % Nonlinear relationship between slip and friction
        mu = mu_max * (1 - exp(-s_max / slip));
    end
end

function slip = calculateSlip(v_vehicle, v_wheel)
    % Calculate slip ratio from vehicle and wheel speeds

    if v_vehicle <= 0
        slip = 0;  % Avoid division by zero or negative speeds
    else
        slip = (v_vehicle - v_wheel) / v_vehicle;  % Slip definition
    end
end

function mod = absCycle(slip, threshold)
    % ABS control logic: torque modulation based on slip threshold

    % Default value if input missing
    if nargin < 2, threshold = 0.15; end

    % Torque modulation: 50% when threshold exceeded, 100% otherwise
    mod = 0.5 * (slip > threshold) + 1.0 * (slip <= threshold);
end

function animateResults(t, v_vehicle, v_wheel, slip, mu, torque, params)
    % Create animated visualization of simulation results

    % Create subplots
    ax(1) = subplot(2,2,1);
    hold on;
    hLine(1) = plot(t(1), v_vehicle(1), 'b', 'LineWidth', 2);
    hLine(2) = plot(t(1), v_wheel(1), 'r', 'LineWidth', 2);
    hold off;
    title('Speeds (m/s)');
    xlabel('Time (s)');
    ylabel('Speed');
    legend('Vehicle', 'Wheel');
    grid on;

    ax(2) = subplot(2,2,2);
    hLine(3) = plot(t(1), slip(1), 'g', 'LineWidth', 2);
    title('Slip Ratio');
    xlabel('Time (s)');
    ylabel('Slip');
    grid on;

    ax(3) = subplot(2,2,3);
    hLine(4) = plot(t(1), mu(1), 'm', 'LineWidth', 2);
    title('Friction Coefficient');
    xlabel('Time (s)');
    ylabel('Friction');
    grid on;

    ax(4) = subplot(2,2,4);
    hLine(5) = plot(t(1), torque(1), 'k', 'LineWidth', 2);
    title('Braking Torque (Nm)');
    xlabel('Time (s)');
    ylabel('Torque');
    grid on;

    % Format all axes
    for i = 1:4
        xlim(ax(i), [0 t(end)]);
    end

    % Set y-axis limits
    ylim(ax(1), [0 max([v_vehicle(:); v_wheel(:)]) * 1.1]);
    ylim(ax(2), [0 max(slip) * 1.1]);
    ylim(ax(3), [0 max(mu) * 1.1]);
    ylim(ax(4), [0 max(torque) * 1.1]);

    % Add parameter text
    paramText = sprintf('m: %.1f kg, R: %.2f m, Threshold: %.2f', ...
                        params.m, params.R, params.threshold);
    sgtitle(paramText);

    % Animation loop
    for k = 1:length(t)
        % Update vehicle and wheel speeds
        set(hLine(1), 'XData', t(1:k), 'YData', v_vehicle(1:k));
        set(hLine(2), 'XData', t(1:k), 'YData', v_wheel(1:k));

        % Update slip
        set(hLine(3), 'XData', t(1:k), 'YData', slip(1:k));

        % Update friction coefficient
        set(hLine(4), 'XData', t(1:k), 'YData', mu(1:k));

        % Update torque
        set(hLine(5), 'XData', t(1:k), 'YData', torque(1:k));

        drawnow limitrate;

        % Pause at start for readability
        if k == 1
            pause(1);
        end
    end
end

function displayParameters(params)
    % Display simulation parameters in command window

    fprintf('\n=== ABS Simulation Parameters ===\n');
    fprintf('Vehicle mass: %.1f kg\n', params.m);
    fprintf('Wheel inertia: %.2f kg·m²\n', params.I);
    fprintf('Tire radius: %.2f m\n', params.R);
