    fprintf('Max torque: %.0f Nm\n', params.torque_max);
    fprintf('ABS threshold: %.2f\n', params.threshold);
    fprintf('Vertical load: %.1f N\n', params.Fz);
    fprintf('===============================\n\n');
end
