        bottomLeft: getCornerDensityWithEdges(image, 0, image.bitmap.height - cornerSize, cornerSize),
        bottomRight: getCornerDensityWithEdges(image, image.bitmap.width - cornerSize, image.bitmap.height - cornerSize, cornerSize)
    };
    return corners;
